async function ownerReservations(){
  const [data,props]=await Promise.all([api('/api/reservations'),api('/api/properties')]);
  const today=new Date(); today.setHours(12,0,0,0);
  const selectedMonth=reservationCalendarMonth||`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}`;
  const monthStart=new Date(selectedMonth+'-01T12:00:00');
  const gridStart=new Date(monthStart); gridStart.setDate(monthStart.getDate()-((monthStart.getDay()+6)%7));
  const days=Array.from({length:42},(_,i)=>{const d=new Date(gridStart);d.setDate(gridStart.getDate()+i);return d});
  const active=data.filter(r=>r.status==='confirmed');
  const inquiries=data.filter(r=>r.status==='inquiry');
  const propertyColors=['#087f8c','#7357d9','#d65b22','#1971c2','#b02e72','#477a36','#8a6418','#52616b'];
  const propColor=p=>propertyColors[Math.max(0,props.findIndex(x=>x.id===p.id))%propertyColors.length];
  const colorFor=r=>propColor(props.find(p=>p.id===r.property_id)||props[0]||{id:'none'});
  const sameDay=(a,b)=>a===b;
  const dateReservations=day=>active.filter(r=>r.arrival_date<=localISODate(day)&&r.departure_date>localISODate(day));
  const cells=days.map(d=>{
    const iso=localISODate(d), stays=dateReservations(d);
    const visible=stays.slice(0,3).map(r=>`<button type="button" class="v21110-calendar-stay" data-res="${r.id}" style="--stay-color:${colorFor(r)}" title="${esc(r.guest_name)} · ${esc(r.property_name||'Property')} · ${fmtDate(r.arrival_date)} → ${fmtDate(r.departure_date)}"><span class="v21110-stay-dot"></span><span class="v21110-stay-name">${esc(r.guest_name||'Guest')}</span><span class="v21110-stay-source">${esc(r.source||'Stay')}</span></button>`).join('');
    const arrival=active.filter(r=>r.arrival_date===iso).length;
    const checkout=active.filter(r=>r.departure_date===iso).length;
    return `<div class="v21110-calendar-day ${d.getMonth()!==monthStart.getMonth()?'outside-month':''} ${iso===localISODate(today)?'is-today':''}" data-day="${iso}"><button class="v21110-day-number" type="button" data-new-day="${iso}" aria-label="Create reservation on ${iso}">${d.getDate()}</button>${arrival||checkout?`<div class="v21110-day-events"><span>${arrival?`<b>${arrival}</b> in`:''}</span><span>${checkout?`<b>${checkout}</b> out`:''}</span></div>`:''}<div class="v21110-day-stays">${visible}${stays.length>3?`<button class="v21110-more-stays" data-day-more="${iso}">+${stays.length-3} more</button>`:''}</div></div>`;
  }).join('');
  const content=`<section class="v21110-reservations-page">
    <header class="v21110-calendar-header"><div><span class="eyebrow">DELVANE · RESERVATIONS</span><h1>Calendar</h1><p>All properties. One clear view.</p></div><button class="btn primary" id="newReservation">＋ New reservation</button></header>
    <section class="v21110-calendar-shell"><div class="v21110-calendar-toolbar"><div class="v21110-month-controls"><button type="button" id="calPrev" aria-label="Previous month">‹</button><button type="button" id="calToday">Today</button><button type="button" id="calNext" aria-label="Next month">›</button><h2>${monthStart.toLocaleDateString(rosaLocaleCode(),{month:'long',year:'numeric'})}</h2></div><label class="v21110-month-picker">Go to month<input id="calMonth" type="month" value="${selectedMonth}"></label><div class="v21110-calendar-view-label">MONTH VIEW</div></div>
    <div class="v21110-calendar-grid"><div class="v21110-weekday">Mon</div><div class="v21110-weekday">Tue</div><div class="v21110-weekday">Wed</div><div class="v21110-weekday">Thu</div><div class="v21110-weekday">Fri</div><div class="v21110-weekday">Sat</div><div class="v21110-weekday">Sun</div>${cells}</div>
    <div class="v21110-calendar-legend"><strong>PROPERTIES</strong>${props.map(p=>`<span><i style="--legend-color:${propColor(p)}"></i>${esc(p.name)}</span>`).join('') || '<span>No properties configured</span>'}<span class="v21110-legend-note"><i class="v21110-checkin-legend"></i> Stay covers check-in through the night before checkout</span></div></section>
    <section class="v21110-calendar-modules"><header><div><span class="eyebrow">WORKSPACE</span><h2>Everything else, close at hand</h2></div></header><div class="v21110-module-links"><button data-module="today"><span>◷</span><b>Today</b><small>Arrivals, departures and priorities</small></button><button data-module="inbox"><span>✉</span><b>Reception</b><small>Guest messages and requests</small></button><button data-module="team"><span>✓</span><b>Team & tasks</b><small>Housekeeping and maintenance</small></button><button data-module="train"><span>R</span><b>Train Delvane</b><small>Property knowledge and rules</small></button></div></section>
    ${inquiries.length?`<section class="v21110-inquiries"><header><div><span class="eyebrow">NOT CONFIRMED</span><h2>Inquiries</h2></div><span>${inquiries.length} awaiting confirmation</span></header>${inquiries.slice(0,8).map(r=>`<button class="v21110-inquiry-row" data-res="${r.id}"><span class="v21110-inquiry-dot"></span><span><b>${esc(r.guest_name||'Guest')}</b><small>${esc(r.property_name||'Property')} · ${fmtDate(r.arrival_date)} → ${fmtDate(r.departure_date)}</small></span><span>${esc(r.source||'Inquiry')} →</span></button>`).join('')}</section>`:''}
  </section>${rosaBar()}`;
  app.innerHTML=shell(content,'reservations'); wireShell(); wireDelvane();
  const moveMonth=delta=>{const d=new Date(selectedMonth+'-01T12:00:00');d.setMonth(d.getMonth()+delta);reservationCalendarMonth=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;ownerReservations()};
  $('#calPrev').onclick=()=>moveMonth(-1); $('#calNext').onclick=()=>moveMonth(1);
  $('#calToday').onclick=()=>{reservationCalendarMonth=null;ownerReservations()};
  $('#calMonth').onchange=e=>{if(e.target.value){reservationCalendarMonth=e.target.value;ownerReservations()}};
  $('#newReservation').onclick=()=>reservationModal(null,props);
  document.querySelectorAll('[data-res]').forEach(el=>el.onclick=()=>reservationModal(data.find(r=>r.id===el.dataset.res),props));
  document.querySelectorAll('[data-new-day]').forEach(el=>el.onclick=()=>{const date=el.dataset.newDay;reservationModal(null,props,date)});
  document.querySelectorAll('[data-day-more]').forEach(el=>el.onclick=()=>{const iso=el.dataset.dayMore;const stays=dateReservations(new Date(iso+'T12:00:00'));const names=stays.map(r=>`${r.guest_name} · ${r.property_name}`).join('\n');alert(`${iso}\n\n${names}`)});
  document.querySelectorAll('[data-module]').forEach(el=>el.onclick=()=>{const map={today:ownerToday,inbox:ownerInbox,team:ownerTeam,train:ownerTrain};if(map[el.dataset.module])map[el.dataset.module]()});
}

async function legacyReservationModal(r,props,initialDate=null){
  const roomTypesByProperty={};
  for(const p of props){try{const out=await api(`/api/properties/${p.id}/room-types`);roomTypesByProperty[p.id]=out.room_types||[]}catch(_){roomTypesByProperty[p.id]=[]}}
  const isEdit=!!r, reqs=requestList(r).join(', ');
  const tomorrow=initialDate?new Date(initialDate+'T12:00:00'):new Date();if(!initialDate)tomorrow.setDate(tomorrow.getDate()+1);
  const after=new Date(tomorrow);after.setDate(after.getDate()+3);
  document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="reservationModal"><form class="modal-card reservation-form" id="reservationForm"><div class="modal-title"><div><span class="eyebrow">${isEdit?'RESERVATION':'NEW RESERVATION'}</span><h2>${isEdit?esc(r.guest_name):'Add a stay'}</h2></div><button type="button" class="modal-x" id="closeReservation">×</button></div>
    <div class="form-grid"><label>Property<select id="rfProperty">${props.map(p=>`<option value="${p.id}" ${r?.property_id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Room type<select id="rfRoomType"></select></label><label>Source<select id="rfSource">${['Direct','Booking.com','Szallas.hu'].map(x=>`<option ${r?.source===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="wide">Guest name<input id="rfGuest" value="${esc(r?.guest_name||'')}" required></label><label>Arrival<input id="rfArrival" type="date" value="${r?.arrival_date||localISODate(tomorrow)}" required></label><label>Departure / checkout<input id="rfDeparture" type="date" value="${r?.departure_date||localISODate(after)}" required></label><div class="stay-duration wide" id="rfStayDuration"></div><label>Guests<input id="rfGuests" type="number" min="1" value="${r?.guest_count||2}" required></label><label>Guest arrival time<input id="rfTime" type="time" value="${r?.arrival_time||''}"></label><label>Total reservation value (HUF)<input id="rfPrice" type="number" min="0" value="${r?.total_huf||''}" placeholder="Optional — not the nightly rate"></label><label>Reference<input id="rfRef" value="${esc(r?.external_ref||'')}" placeholder="Optional"></label><label class="wide">Special preparation<input id="rfRequests" value="${esc(reqs)}" placeholder="High chair, baby cot, extra towels"></label></div>
    <p class="form-error" id="rfError"></p><div class="modal-actions">${isEdit&&r.status==='inquiry'?'<button type="button" class="btn confirm-booking" id="confirmReservation">Confirm booking</button>':''}${isEdit?'<button type="button" class="btn danger" id="cancelReservation">Cancel reservation</button>':''}<button type="button" class="btn" id="closeReservation2">Close</button><button class="btn primary" type="submit">${isEdit?'Save changes':'Create reservation'}</button></div></form></div>`);

  const close=()=>$('#reservationModal')?.remove();
  $('#closeReservation').onclick=close;
  $('#closeReservation2').onclick=close;
  $('#reservationModal').onclick=e=>{if(e.target.id==='reservationModal')close()};
  const refreshRoomTypes=()=>{const list=roomTypesByProperty[$('#rfProperty').value]||[];$('#rfRoomType').innerHTML=list.map(rt=>`<option value="${rt.id}" ${r?.room_type_id===rt.id?'selected':''}>${esc(rt.name)} · inventory ${rt.inventory_count} unit${rt.inventory_count===1?'':'s'}</option>`).join('');};
  $('#rfProperty').onchange=refreshRoomTypes;refreshRoomTypes();
  const updateStayDuration=()=>{const arrival=$('#rfArrival').value,departure=$('#rfDeparture').value,nights=stayNights(arrival,departure),box=$('#rfStayDuration');if(!arrival||!departure||nights<1){box.classList.add('invalid');box.innerHTML='<b>Choose a valid stay</b><span>Departure must be after arrival.</span>';return}box.classList.remove('invalid');box.innerHTML=`<b>${nights} night${nights===1?'':'s'}</b><span>Occupied nights: ${fmtDate(arrival)} through ${fmtDate(previousISODate(departure))}. Checkout: ${fmtDate(departure)}; that night remains available.</span>`};
  $('#rfArrival').addEventListener('change',updateStayDuration);$('#rfDeparture').addEventListener('change',updateStayDuration);updateStayDuration();
  $('#reservationForm').onsubmit=async e=>{
    e.preventDefault();
    const body={
      property_id:$('#rfProperty').value,
      room_type_id:$('#rfRoomType').value||null,
      source:$('#rfSource').value,
      guest_name:$('#rfGuest').value,
      arrival_date:$('#rfArrival').value,
      departure_date:$('#rfDeparture').value,
      guest_count:Number($('#rfGuests').value),
      arrival_time:$('#rfTime').value||null,
      total_huf:$('#rfPrice').value?Number($('#rfPrice').value):null,
      external_ref:$('#rfRef').value||null,
      special_requests:$('#rfRequests').value.split(',').map(x=>x.trim()).filter(Boolean)
    };
    try{
      const out=await api(isEdit?`/api/reservations/${r.id}`:'/api/reservations',{method:isEdit?'PATCH':'POST',body:JSON.stringify(body)});
      const delivered=(out.channex_delivery?.delivered||[]).filter(x=>(x.task_ids||[]).length);
      close();
      const showAvailabilityResult=(items,pending=false)=>{
        const ids=items.flatMap(x=>x.task_ids||[]);
        const title=ids.length?'Availability update delivered':'Availability update queued';
        const detail=ids.length?'Channex accepted the availability change.':'The change is safely queued in Delvane and will be delivered automatically.';
        document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="reservationChannexResult"><div class="modal-card receiver-result-card"><div class="connection-success-mark">${ids.length?'✓':'↻'}</div><span class="eyebrow">CHANNEL DISTRIBUTION</span><h2>${title}</h2><p>${esc(body.guest_name)} · ${esc(body.arrival_date)} → ${esc(body.departure_date)}</p><p class="muted">${detail}</p>${ids.length?`<div class="ari-task-list">${items.map(x=>`<div><span>Availability</span><b>${esc((x.task_ids||[]).join(', '))}</b></div>`).join('')}</div>`:''}<div class="modal-actions"><button class="btn primary" id="reservationChannexDone">Done</button></div></div></div>`);
        $('#reservationChannexDone').onclick=()=>$('#reservationChannexResult')?.remove();
      };
      if(delivered.length){
        showAvailabilityResult(delivered);
      }else{
        let attempts=0;
        const poll=async()=>{
          attempts++;
          try{
            const status=await api(`/api/reservations/${out.id}/channex-availability-delivery`);
            if(status.delivered?.length){ showAvailabilityResult(status.delivered); return; }
          }catch(_){}
          if(attempts<10){ setTimeout(poll,1500); }
          else { showAvailabilityResult([],true); }
        };
        setTimeout(poll,800);
      }
      ownerReservations();
    }catch(err){$('#rfError').textContent=err.message;}
  };
  if(isEdit && r.status==='inquiry') $('#confirmReservation').onclick=async()=>{
    try{
      await api(`/api/reservations/${r.id}`,{method:'PATCH',body:JSON.stringify({status:'confirmed'})});
      close();
      ownerReservations();
    }catch(err){$('#rfError').textContent=err.message;}
  };
  if(isEdit) $('#cancelReservation').onclick=async()=>{
    if(!confirm(`Cancel ${r.guest_name}'s reservation?`)) return;
    try{
      const out=await api(`/api/reservations/${r.id}`,{method:'DELETE'});
      close();
      ownerReservations();
      const delivered=(out.channex_delivery?.delivered||[]).filter(x=>(x.task_ids||[]).length);
      const show=(items,pending=false)=>{
        const ids=items.flatMap(x=>x.task_ids||[]);
        document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="reservationChannexResult"><div class="modal-card receiver-result-card"><div class="connection-success-mark">${ids.length?'✓':'↻'}</div><span class="eyebrow">CHANNEL DISTRIBUTION</span><h2>${ids.length?'Cancellation availability delivered':'Cancellation availability queued'}</h2><p>${esc(r.guest_name)} · ${fmtDate(r.arrival_date)} → ${fmtDate(r.departure_date)}</p><p class="muted">${ids.length?'Channex accepted the availability restoration.':'Delvane has queued the availability restoration and will retry automatically.'}</p>${ids.length?`<div class="ari-task-list">${items.map(x=>`<div><span>Availability</span><b>${esc((x.task_ids||[]).join(', '))}</b></div>`).join('')}</div>`:''}<div class="modal-actions"><button class="btn primary" id="reservationChannexDone">Done</button></div></div></div>`);
        $('#reservationChannexDone').onclick=()=>$('#reservationChannexResult')?.remove();
      };
      if(delivered){show(delivered);}
      else{
        let attempts=0;
        const poll=async()=>{
          attempts++;
          try{const status=await api(`/api/reservations/${r.id}/channex-availability-delivery`);if(status.delivered?.length){show(status.delivered);return;}}catch(_){}
          if(attempts<20)setTimeout(poll,1000); else show([],true);
        };
        setTimeout(poll,300);
      }
    }catch(err){$('#rfError').textContent=err.message;}
  };
}


function inboxStatusLabel(status){
  return ({new:'New',analyzed:'Analyzed',actioned:'Actions applied',replied:'Replied'})[status]||status;
}

function inboxStatusClass(status){
  return status==='new'?'attention':status==='analyzed'?'cleaning':status==='replied'?'ready':'ready';
}
function authorityModeLabel(mode){
  return ({auto:'Handle automatically',ask:'Ask owner',never:'Never without owner'})[mode]||mode;
}
function authorityClass(mode){ return mode==='auto'?'auto':mode==='never'?'never':'ask'; }

function analysisValue(label,value){
  if(value===null || value===undefined || value==='' || (Array.isArray(value)&&!value.length)) return '';
  const shown=Array.isArray(value)?value.join(', '):value;
  return `<div class="analysis-field"><span>${esc(label)}</span><b>${esc(shown)}</b></div>`;
}

async function ownerInbox(selectedId=null,forceList=false){
  const [items,props,reservations]=await Promise.all([api('/api/inbox'),api('/api/properties'),api('/api/reservations')]);
  if(selectedId!==null && selectedId!==undefined) activeInboxId=String(selectedId);
  if(forceList) activeInboxId=null;
  else if(!activeInboxId || !items.some(x=>String(x.id)===String(activeInboxId))) activeInboxId=items[0] ? String(items[0].id) : null;
  const selected=items.find(x=>String(x.id)===String(activeInboxId))||null;
  const newCount=items.filter(x=>x.status==='new').length;
  const waitingCount=items.filter(x=>x.status==='analyzed').length;

  const list=items.length?items.map((m,i)=>`<button type="button" class="inbox-item ${m.id===activeInboxId?'active':''}" data-message="${m.id}" data-search-text="${esc(`${m.sender_name||''} ${m.subject||''} ${m.body||''} ${m.source||''}`.toLowerCase())}">
    <span class="gmail-avatar gmail-avatar-${i%6}">${esc((m.sender_name||m.source||'?').trim().charAt(0).toUpperCase())}</span>
    <span class="gmail-message-copy"><span class="gmail-row-top"><b>${esc(m.sender_name||'Unknown sender')}</b><time>${esc(m.received_at||m.created_at||'')}</time></span>
    <span class="gmail-subject">${esc(m.subject||'No subject')}</span>
    <span class="gmail-snippet">${esc((m.body||'').replace(/\s+/g,' ').slice(0,105))}${(m.body||'').length>105?'…':''}</span>
    <span class="gmail-source-line"><span>${esc(m.source||'Message')}</span>${m.status==='new'?'<i class="gmail-unread-dot" aria-label="Unread"></i>':''}</span></span>
  </button>`).join(''):`<div class="gmail-empty">Your inbox is clear.<small>Guest messages will appear here.</small></div>`;

  const detail=selected?`<div class="v21110-mobile-thread-head"><button type="button" id="mobileInboxBack" aria-label="Back to inbox">‹ <span>Inbox</span></button><b>${esc(selected.sender_name||'Message')}</b></div>${inboxDetail(selected)}`:`<div class="empty tall">Select a message to review it.</div>`;

  const content=`<section class="top compact inbox-top"><div><span class="eyebrow">ROSA INBOX</span><h1>Messages become actions.</h1><p>Delvane extracts what matters, shows what it intends to change, and keeps you in control before anything operational happens.</p></div><button class="btn primary" id="newInboxMessage">+ Paste message</button></section>
    <section class="inbox-metrics"><article><span>New</span><strong>${newCount}</strong></article><article><span>Waiting for approval</span><strong>${waitingCount}</strong></article><article><span>Total active</span><strong>${items.length}</strong></article></section>
    <section class="inbox-layout ${selected?'v21110-mobile-message-open':''}"><div class="inbox-list-panel"><div class="gmail-mobile-search"><button type="button" class="gmail-menu-icon" aria-label="Open navigation">☰</button><input id="gmailInboxSearch" type="search" placeholder="Search in mail" aria-label="Search in mail"><span class="gmail-profile">R</span></div><div class="gmail-mobile-label">All inboxes <span>${newCount||''}</span></div><div class="v21110-mobile-inbox-heading"><h2>Inbox</h2></div><div class="gmail-message-list">${list}</div></div><div class="inbox-detail-panel">${detail}</div></section>${rosaBar()}`;

  app.innerHTML=shell(content,'inbox');
  wireShell(); wireDelvane();
  document.querySelectorAll('[data-message]').forEach(b=>b.onclick=()=>ownerInbox(b.dataset.message));
  $('#newInboxMessage').onclick=()=>newInboxModal(props,reservations);
  $('#gmailInboxSearch')?.addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();document.querySelectorAll('.gmail-message-list [data-message]').forEach(row=>{row.hidden=!row.dataset.searchText.includes(q)})});
  document.querySelector('.gmail-menu-icon')?.addEventListener('click',()=>$('#mobileMenuBtn')?.click());
  $('#mobileInboxBack')?.addEventListener('click',()=>{activeInboxId=null;ownerInbox(null,true)});
  if(selected) wireInboxDetail(selected);
}

function inboxDetail(m){
  const a=m.analysis||{};
  const ex=a.extracted||{};
  const analyzed=Object.keys(a).length>0;
  return `<div class="inbox-detail">
    <div class="inbox-detail-head"><div><span class="source">${esc(m.source)} · ${inboxStatusLabel(m.status)}</span><h2>${esc(m.sender_name||'Unknown sender')}</h2><p>${esc(m.sender_contact||m.subject||'')}</p></div><button class="text-btn" id="archiveMessage">Archive</button></div>
    <div class="message-paper"><span class="eyebrow">${esc(m.subject||'MESSAGE')}</span><p>${esc(m.body)}</p></div>
    ${m.reservation_id?`<button class="linked-reservation" id="openLinkedReservation"><span>LINKED RESERVATION</span><b>${esc(m.reservation_guest||'Reservation')} · ${fmtDate(m.reservation_arrival)} → ${fmtDate(m.reservation_departure)}</b><small>Open reservation →</small></button>`:''}
    ${!analyzed?`<div class="analyze-empty"><img class="delvane-primary-logo rosa-large-logo" src="/static/delvane-icon.png" alt="Delvane logo"><h3>Ready to interpret this message</h3><p>Delvane will extract the request, consult your property knowledge, and show which actions it may handle automatically or must ask you about.</p><button class="btn primary" id="analyzeMessage">Analyze with Delvane</button></div>`:`
      <section class="analysis-card"><div class="analysis-title"><span class="eyebrow">ROSA UNDERSTOOD</span><span class="state ${a.availability==='unavailable'?'attention':'ready'}">${a.kind==='inquiry'?(a.availability==='available'?'Available':'Inquiry'):'Existing guest'}</span></div>
        <div class="analysis-grid">
          ${analysisValue('Property',ex.property_name)}
          ${analysisValue('Arrival date',ex.arrival_date?fmtDate(ex.arrival_date):'')}
          ${analysisValue('Departure date',ex.departure_date?fmtDate(ex.departure_date):'')}
          ${analysisValue('Guests',ex.guest_count)}
          ${analysisValue('Arrival time',ex.arrival_time)}
          ${analysisValue('Preparation',ex.special_requests)}
        </div>
        ${a.unresolved?.length?`<div class="unresolved"><span>NEEDS OWNER KNOWLEDGE</span>${a.unresolved.map(x=>`<p>• ${esc(x)}</p>`).join('')}</div>`:''}
      </section>
      ${a.knowledge_used?.length?`<section class="knowledge-used-card"><div class="analysis-title"><span class="eyebrow">ROSA USED YOUR KNOWLEDGE</span><span class="knowledge-count">${a.knowledge_used.length} answer${a.knowledge_used.length===1?'':'s'}</span></div>${a.knowledge_used.map(k=>`<div class="knowledge-used"><div><b>${esc(k.label)}</b><span>${k.scope==='shared'?'Casa Rosa shared knowledge':'Property-specific knowledge'}</span></div><p>${esc(k.value)}</p></div>`).join('')}</section>`:''}
      <section class="action-card"><span class="eyebrow">PROPOSED ACTIONS</span>
        ${a.auto_applied?.length?`<div class="auto-applied"><b>${me?.operating_mode==='observe'?'◌ SIMULATION — no operational data changed':'✓ Delvane already handled automatically'}</b>${a.auto_applied.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}
        ${a.proposed_actions?.length?a.proposed_actions.map(x=>`<div class="proposed-action"><span>✓</span><div><b>${esc(x.label)}</b><small class="authority-chip ${authorityClass(x.authority_mode)}">${authorityModeLabel(x.authority_mode)}</small></div></div>`).join(''):'<p class="muted">No database changes are needed from this message.</p>'}
      </section>
      <section class="reply-card"><div><span class="eyebrow">SUGGESTED REPLY</span><div class="reply-meta"><small>Editable before sending</small>${a.knowledge_used?.length?`<span class="authority-chip ${authorityClass(a.reply_authority)}">${authorityModeLabel(a.reply_authority)}</span>`:''}</div></div><textarea id="draftReply">${esc(m.draft_reply||a.draft_reply||'')}</textarea></section>
      <div class="inbox-actions">
        ${m.status==='analyzed'?`<button class="btn primary" id="applyInboxActions">${me?.operating_mode==='observe'?'Simulate proposed actions':(a.kind==='inquiry'?'Create inquiry & save actions':'Approve & apply actions')}</button>`:''}
        ${(m.status==='analyzed'||m.status==='actioned')?`<button class="btn" id="markReplySent">Mark reply as sent</button>`:''}
        ${m.status==='replied'?`<span class="sent-note">✓ Reply marked as sent</span>`:''}
      </div>
    `}
  </div>`;
}

function wireInboxDetail(m){
  $('#analyzeMessage')?.addEventListener('click',async()=>{
    await api(`/api/inbox/${m.id}/analyze`,{method:'POST'});
    await ownerInbox(m.id);
  });
  $('#applyInboxActions')?.addEventListener('click',async()=>{
    const d=await api(`/api/inbox/${m.id}/apply`,{method:'POST',body:JSON.stringify({draft_reply:$('#draftReply')?.value||null})});
    if(d.reservation_id) activeInboxId=m.id;
    await ownerInbox(m.id);
  });
  $('#markReplySent')?.addEventListener('click',async()=>{
    await api(`/api/inbox/${m.id}/reply-sent`,{method:'POST',body:JSON.stringify({draft_reply:$('#draftReply')?.value||null})});
    await ownerInbox(m.id);
  });
  $('#archiveMessage')?.addEventListener('click',async()=>{
    await api(`/api/inbox/${m.id}/archive`,{method:'POST'});
    activeInboxId=null;
    await ownerInbox();
  });
  $('#openLinkedReservation')?.addEventListener('click',()=>openReservationById(m.reservation_id));
}

function newInboxModal(props,reservations){
  document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="inboxModal"><form class="modal-card inbox-form" id="inboxForm">
    <div class="modal-title"><div><span class="eyebrow">NEW INBOX ITEM</span><h2>Paste a guest message</h2></div><button type="button" class="modal-x" id="closeInboxModal">×</button></div>
    <div class="form-grid">
      <label>Source<select id="imSource"><option>Direct email</option><option>Booking.com</option><option>Szallas.hu</option><option>Phone / manual</option></select></label>
      <label>Property<select id="imProperty"><option value="">Let Delvane detect it</option>${props.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label>
      <label>Sender name<input id="imSender" placeholder="Guest name"></label>
      <label>Contact<input id="imContact" placeholder="Email or phone, optional"></label>
      <label class="wide">Link to existing reservation<select id="imReservation"><option value="">New inquiry / not linked</option>${reservations.filter(r=>r.status==='confirmed').map(r=>`<option value="${r.id}">${esc(r.guest_name)} · ${esc(r.property_name)} · ${fmtDate(r.arrival_date)}</option>`).join('')}</select></label>
      <label class="wide">Subject<input id="imSubject" placeholder="Optional"></label>
      <label class="wide">Message<textarea id="imBody" placeholder="Paste the guest's message here…" required></textarea></label>
    </div><p class="form-error" id="imError"></p><div class="modal-actions"><button type="button" class="btn" id="closeInboxModal2">Cancel</button><button class="btn primary" type="submit">Add to Inbox</button></div>
  </form></div>`);
  const close=()=>$('#inboxModal')?.remove();
  $('#closeInboxModal').onclick=close; $('#closeInboxModal2').onclick=close;
  $('#inboxModal').onclick=e=>{if(e.target.id==='inboxModal')close()};
  $('#inboxForm').onsubmit=async e=>{
    e.preventDefault();
    try{
      const body={
        source:$('#imSource').value,
        sender_name:$('#imSender').value,
        sender_contact:$('#imContact').value,
        subject:$('#imSubject').value,
        body:$('#imBody').value,
        property_id:$('#imProperty').value||null,
        reservation_id:$('#imReservation').value||null
      };
      const d=await api('/api/inbox',{method:'POST',body:JSON.stringify(body)});
      close(); await ownerInbox(d.id);
    }catch(err){$('#imError').textContent=err.message;}
  };
}

async function ownerTrainDelvane(scopeId=null){
  const d=await api('/api/knowledge');
  if(scopeId) activeKnowledgeScope=scopeId;
  const valid=['shared',...d.properties.map(p=>p.id)];
  if(!valid.includes(activeKnowledgeScope)) activeKnowledgeScope='shared';
  const scopeName=activeKnowledgeScope==='shared'?'Casa Rosa · shared':d.properties.find(p=>p.id===activeKnowledgeScope)?.name||'Property';
  const values=d.scopes[activeKnowledgeScope]||{};
  const filled=Object.values(values).filter(v=>String(v||'').trim()).length;
  const tabs=[['shared','Casa Rosa'],...d.properties.map(p=>[p.id,p.name])].map(([id,label])=>`<button type="button" class="knowledge-tab ${id===activeKnowledgeScope?'active':''}" data-scope="${id}">${esc(label)}</button>`).join('');
  const categories=[...new Set(d.fields.map(f=>f.category))];
  const fields=categories.map(cat=>`<section class="knowledge-group"><div class="knowledge-group-title"><span class="eyebrow">${esc(cat)}</span></div><div class="knowledge-fields">${d.fields.filter(f=>f.category===cat).map(f=>`<label class="knowledge-field"><div><b>${esc(f.label)}</b><span>${values[f.key]?.trim()?'Configured':'Not configured'}</span></div><textarea data-knowledge-key="${f.key}" placeholder="Tell Delvane exactly what it should know…">${esc(values[f.key]||'')}</textarea></label>`).join('')}</div></section>`).join('');
  const authority=Object.entries(d.authority).map(([key,rule])=>`<article class="authority-row"><div><b>${esc(rule.label)}</b><span>${esc(rule.category)}</span></div><select data-authority="${key}"><option value="auto" ${rule.mode==='auto'?'selected':''}>Handle automatically</option><option value="ask" ${rule.mode==='ask'?'selected':''}>Ask owner</option><option value="never" ${rule.mode==='never'?'selected':''}>Never without owner</option></select></article>`).join('');

  const content=`<section class="top compact train-top"><span class="eyebrow">TRAIN ROSA</span><h1>Teach Delvane how Casa Rosa works.</h1><p>These are the facts Delvane is allowed to use when answering guests. Property-specific knowledge overrides shared Casa Rosa knowledge.</p></section>
  <section class="demo-warning"><b>Prototype knowledge</b><span>The seeded entries marked “DEMO ONLY” are placeholders, not real Casa Rosa policies. Replace them before guest messaging goes live.</span></section>
  <section class="knowledge-shell"><div class="knowledge-tabs">${tabs}</div><div class="knowledge-editor"><div class="knowledge-editor-head"><div><span class="eyebrow">EDITING</span><h2>${esc(scopeName)}</h2><p>${activeKnowledgeScope==='shared'?'Used as a fallback for every apartment.':'Overrides shared answers for this apartment.'}</p></div><div class="knowledge-score"><strong>${filled}</strong><span>of ${d.fields.length}<br>configured</span></div></div>${fields}<div class="knowledge-savebar"><span id="knowledgeSaveState">Changes stay local until you save them.</span><button class="btn primary" id="saveKnowledge">Save ${activeKnowledgeScope==='shared'?'shared knowledge':esc(scopeName)}</button></div></div></section>
  <section class="authority-section"><div class="section-head"><div><span class="eyebrow">AUTHORITY</span><h2>Decide what Delvane may do.</h2></div></div><p class="authority-intro">This is deliberately granular. A Wi-Fi answer can eventually be automatic while discounts and refunds still require you.</p><div class="authority-list">${authority}</div><div class="authority-legend"><span><i class="auth-dot auto"></i> Automatic = Delvane may perform the operational action during analysis</span><span><i class="auth-dot ask"></i> Ask owner = Delvane proposes it for approval</span><span><i class="auth-dot never"></i> Never = Delvane will not perform it</span></div></section>${rosaBar()}`;

  app.innerHTML=shell(content,'train');
  wireShell(); wireDelvane();
  document.querySelectorAll('[data-scope]').forEach(b=>b.onclick=()=>ownerTrainDelvane(b.dataset.scope));
  $('#saveKnowledge').onclick=async()=>{
    const entries={};
    document.querySelectorAll('[data-knowledge-key]').forEach(el=>entries[el.dataset.knowledgeKey]=el.value);
    const state=$('#knowledgeSaveState');
    state.textContent='Saving…';
    try{
      await api(`/api/knowledge/${activeKnowledgeScope}`,{method:'PUT',body:JSON.stringify({entries})});
      state.textContent='✓ Saved. Delvane will use this on the next analysis.';
      setTimeout(()=>ownerTrainDelvane(activeKnowledgeScope),550);
    }catch(err){ state.textContent=err.message; }
  };
  document.querySelectorAll('[data-authority]').forEach(sel=>sel.onchange=async()=>{
    const old=sel.dataset.saved||'';
    sel.disabled=true;
    try{
      await api(`/api/authority/${sel.dataset.authority}`,{method:'PATCH',body:JSON.stringify({mode:sel.value})});
      sel.classList.add('saved-flash'); setTimeout(()=>sel.classList.remove('saved-flash'),700);
    }catch(err){ if(old) sel.value=old; alert(err.message); }
    finally{ sel.disabled=false; sel.dataset.saved=sel.value; }
  });
}


async function ownerTeam(){
  const d=await api('/api/owner/dashboard');
  const content=`<section class="top compact"><span class="eyebrow">TEAM</span><h1>Delvane coordinates the handoff.</h1><p>Your cleaner sees only the work they need. Reservation changes flow into their schedule automatically.</p></section><section class="table-card"><div class="reservation-list">${d.worker_tasks.map(t=>`<article><div><span class="source">${fmtDate(t.scheduled_date)} ${t.earliest_time||''}</span><h3>${esc(t.title)}</h3><p>${esc(t.detail)}</p></div><div class="res-right"><b>${esc(t.assigned_name||'Unassigned')}</b><span class="registration ${t.status==='complete'?'complete':'incomplete'}">${statusLabel(t.status)}</span></div></article>`).join('')}</div></section>${rosaBar()}`;
  app.innerHTML=shell(content,'team');
  wireShell();
  wireDelvane();
}

async function workerToday(schedule=false){
  const d=await api('/api/worker/dashboard');
  const today=d.date;
  const tasks=schedule?d.tasks:d.tasks.filter(t=>t.scheduled_date===today || t.status==='in_progress');
  const content=`<section class="top"><span class="eyebrow">${schedule?'YOUR SCHEDULE':'TODAY'}</span><h1>${schedule?'Upcoming work.':'Everything you need.'}</h1><p>${schedule?'Your schedule updates automatically when reservations change.':'No booking system to learn. Delvane shows only the work assigned to you.'}</p></section>
  <section class="worker-list">${tasks.length?tasks.map(taskCard).join(''):'<div class="empty tall">No cleaning is assigned here right now.</div>'}</section>${rosaBar()}`;
  app.innerHTML=shell(content,schedule?'schedule':'today');
  wireShell();
  wireDelvane();
  wireTasks();
}
function taskCard(t){
  const reqs=t.special_requests||[];
  return `<article class="worker-card ${t.priority==='high'?'turnaround':''}" data-task="${t.id}"><div class="worker-date"><span>${fmtDate(t.scheduled_date)}</span>${t.deadline_time?`<b>${t.earliest_time||'—'} → ${t.deadline_time}</b>`:'<b>Flexible</b>'}</div><div class="worker-title"><h2>${esc(t.property_name)}</h2><span class="state ${t.status==='complete'?'ready':t.status==='in_progress'?'cleaning':'attention'}">${statusLabel(t.status)}</span></div><p>${esc(t.detail)}</p>${reqs.length?`<div class="special"><span>SPECIAL PREPARATION</span>${reqs.map(x=>`<label><input type="checkbox"> ${esc(x)}</label>`).join('')}</div>`:''}<div class="checklist"><label><input type="checkbox"> Bedding</label><label><input type="checkbox"> Bathroom</label><label><input type="checkbox"> Kitchen</label><label><input type="checkbox"> Towels & supplies</label><label><input type="checkbox"> Floors</label><label><input type="checkbox"> Final check</label></div><div class="task-actions">${t.status==='open'?`<button class="btn primary start-task" data-id="${t.id}">Start cleaning</button>`:t.status==='in_progress'?`<button class="btn primary finish-task" data-id="${t.id}">Finish cleaning</button>`:`<button class="btn done" disabled>Finished ${t.finished_at?new Date(t.finished_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):''}</button>`}</div></article>`;
}
function wireTasks(){
  document.querySelectorAll('.start-task').forEach(b=>b.onclick=async()=>{
    await api(`/api/work-tasks/${b.dataset.id}/start`,{method:'POST'});
    await workerToday(false);
  });
  document.querySelectorAll('.finish-task').forEach(b=>b.onclick=()=>openFinish(b.dataset.id));
}
function openFinish(id){
  activeTask=id;
  const modal=document.createElement('div');
  modal.className='modal';
  modal.innerHTML=`<div class="modal-card"><span class="eyebrow">FINISH CLEANING</span><h2>Anything the owner should know?</h2><textarea id="workerNote" placeholder="Optional note: low on coffee capsules, leaking tap, stain on sheet…"></textarea><div class="modal-actions"><button class="btn" id="cancelFinish">Cancel</button><button class="btn primary" id="confirmFinish">Mark ready</button></div></div>`;
  document.body.append(modal);
  $('#cancelFinish').onclick=()=>modal.remove();
  $('#confirmFinish').onclick=async()=>{
    await api(`/api/work-tasks/${id}/finish`,{method:'POST',body:JSON.stringify({note:$('#workerNote').value})});
    modal.remove();
    await workerToday(false);
  };
}

function rosaBar(){return `<div class="rosa-bar"><img class="delvane-assistant-icon" src="/static/delvane-icon.png" alt="Delvane"><input id="rosaInput" placeholder="Ask Delvane anything…"><button id="rosaAsk">Ask</button></div><div id="rosaReply" class="rosa-reply"></div>`;}
function wireDelvane(){
  $('#rosaAsk')?.addEventListener('click',ask);
  $('#rosaInput')?.addEventListener('keydown',e=>{if(e.key==='Enter')ask();});
}
async function ask(){
  const input=$('#rosaInput');
  if(!input.value.trim()) return;
  const d=await api('/api/rosa/ask',{method:'POST',body:JSON.stringify({message:input.value})});
  const box=$('#rosaReply');
  box.textContent=d.answer;
  box.classList.add('show');
  input.value='';
}

async function navigate(v){
  if(['owner','manager'].includes(me.role)){
    if(v==='reservations') return ownerReservations();
    if(v==='inbox') return ownerInbox();
    if(v==='train') return ownerTrainDelvane();
    if(v==='team') return ownerTeam();
    return ownerToday();
  }
  return workerToday(v==='schedule');
}
async function boot(){
  try{
    me=await api('/api/me');
    await navigate('today');
  }catch(e){
    if(!me) renderLogin();
  }
}


