function translateRenderedUI(){
 const map=FULL_LOCALE[uiLang]||{};
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
 const nodes=[]; while(walker.nextNode()) nodes.push(walker.currentNode);
 for(const n of nodes){const raw=n.nodeValue, key=raw.trim(); if(!key) continue; if(map[key]) n.nodeValue=raw.replace(key,map[key]);}
 document.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(el=>{const k=el.getAttribute('placeholder');if(map[k])el.setAttribute('placeholder',map[k]);});
 document.documentElement.lang=uiLang;
}
const localeObserver=new MutationObserver(()=>{clearTimeout(window.__rosaLocaleTimer);window.__rosaLocaleTimer=setTimeout(translateRenderedUI,0)});
localeObserver.observe(document.documentElement,{childList:true,subtree:true});


