function v22(k){return (V22_I18N[uiLang]||V22_I18N.en)[k]||V22_I18N.en[k]||k}

function shell(content, nav='today'){
  currentNav=nav;
  const owner=['owner','manager'].includes(me.role);
  const navItems=owner?[
    ['today',tr('today')],['intelligence',tr('intelligence')],['reservations',tr('reservations')],
    ['guests',v22('guests')],['registration',v22('registration')],['inbox',tr('inbox')],['operations',tr('operations')],
    ['integrations',v22('integrations')],['simulation',v22('simulation')],['maintenance',tr('maintenance')],
    ['supplies',tr('supplies')],['train',tr('train')],['security',v22('security')],['team',tr('team')]
  ]:me.role==='maintenance'?[['maintenance',tr('maintenance')]]:[['today',tr('myday')],['schedule',tr('schedule')],['maintenance',tr('maintenance')]];
  const mode=me?.operating_mode||'observe';
  return `<div class="shell v2-shell v22-shell"><aside class="side"><div class="brand"><img class="delvane-logo side-logo" src="/static/delvane-icon.png" alt="Delvane logo"><div><b>DELVANE</b><span>INTELLIGENCE OS</span></div></div>
  <nav>${navItems.map(([id,label])=>`<button class="nav ${id===nav?'active':''}" data-nav="${id}">${label}</button>`).join('')}</nav>
  ${owner?`<button class="mode-side mode-${mode}" data-nav="simulation"><span>${v22(mode)}</span><small>${v22('currentMode')}</small></button>`:''}
  <div class="side-system"><span class="system-dot"></span><small>DELVANE ONLINE</small></div>
  <div class="side-user"><span>${esc(me.full_name)}</span><small>${roleLabel(me.role)}</small>${langSelect()}<button id="logout">${tr('logout')}</button></div></aside>
  <main class="main"><header class="mobile-head"><div class="brand"><img class="delvane-logo mobile-logo" src="/static/delvane-icon.png" alt="Delvane logo"><b>DELVANE</b></div><div class="mobile-tools">${owner?`<button class="search-launch" id="globalSearchBtnMobile" aria-label="${v22('search')}">⌕</button>`:''}<span class="role-pill">${roleLabel(me.role)}</span></div></header>${owner?`<div class="v22-utility"><button class="search-launch wide" id="globalSearchBtn">⌕ <span>${v22('search')}</span><kbd>Ctrl K</kbd></button><span class="mode-badge mode-${mode}">${v22(mode)}</span></div>`:''}${content}</main></div>`;
}

function wireShell(){
  $('#logout')?.addEventListener('click',async()=>{await api('/api/logout',{method:'POST'});me=null;csrfToken=null;sessionStorage.removeItem('rosa_welcomed');renderLogin()});
  document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));
  $('#globalSearchBtn')?.addEventListener('click',openGlobalSearch);
  $('#globalSearchBtnMobile')?.addEventListener('click',openGlobalSearch);
  if(!window.__rosaSearchKey){window.__rosaSearchKey=true;document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&me&&['owner','manager'].includes(me.role)){e.preventDefault();openGlobalSearch()}})}
  wireLanguage();
}

function wireEntrySlider(){
  const track=$('#enterDelvaneSlider'),knob=$('#enterDelvane');if(!track||!knob)return;
  const enter=()=>{
    if(track.dataset.entering==='1')return;
    track.dataset.entering='1';track.classList.add('entry-launching');
    knob.setAttribute('aria-busy','true');knob.textContent='✓';
    track.setAttribute('aria-valuenow','100');
    sessionStorage.setItem('rosa_welcomed','1');
    window.setTimeout(()=>ownerIntelligence(),260);
  };
  knob.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();enter()});
  track.addEventListener('click',e=>{if(e.target!==knob)enter()});
  track.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();enter()}});
}

async function showDelvaneWelcome(){
  if(!['owner','manager'].includes(me.role)){sessionStorage.setItem('rosa_welcomed','1');return navigate(me.role==='maintenance'?'maintenance':'today')}
  const d=await api('/api/intelligence'),mode=me?.operating_mode||'observe';
  app.innerHTML=`<div class="rosa-entry"><div class="entry-grid"></div><div class="entry-scan"></div><div class="orbital orbital-a"></div><div class="orbital orbital-b"></div><div class="entry-core"><div class="entry-mark"><img class="delvane-primary-logo" src="/static/delvane-icon.png" alt="Delvane logo"></div><div class="entry-kicker">DELVANE INTELLIGENCE SYSTEM / ${v22(mode)}</div><h1>${tr('welcome')}</h1><p class="entry-review">${tr('reviewed')}</p><div class="entry-brief">${esc(d.brief)}</div><div class="entry-stats"><div><strong>${d.approvals.length}</strong><span>${tr('needs')}</span></div><div><strong>${d.handled}</strong><span>${tr('handled')}</span></div><div><strong>${d.exceptions.length}</strong><span>exceptions detected</span></div></div><div class="entry-slider" id="enterDelvaneSlider" role="button" aria-valuenow="0" tabindex="0"><div class="entry-slider-fill"></div><span class="entry-slider-label">${tr('enter')}</span><button type="button" class="entry-slider-knob" id="enterDelvane" aria-label="${tr('enter')}">→</button></div></div><div class="entry-status"><span>${esc(me.organization_name)}</span><b>${v22(mode)} · SECURITY FOUNDATION ACTIVE</b></div></div>`;
  wireEntrySlider();
}

async function ownerGuests(){
 const guests=await api('/api/guests'),returning=guests.filter(g=>g.stays>1).length,upcoming=guests.filter(g=>g.next_stay).length;
 const content=`<section class="top compact"><span class="eyebrow">GUEST INTELLIGENCE</span><h1>${v22('guestTitle')}</h1><p>${v22('guestDesc')}</p></section><section class="intel-metrics v22-metrics"><article><span>${v22('guests')}</span><strong>${guests.length}</strong></article><article><span>${v22('returning')}</span><strong>${returning}</strong></article><article><span>${v22('upcoming')}</span><strong>${upcoming}</strong></article></section><section class="guest-profile-grid">${guests.length?guests.map(g=>`<button class="guest-profile-card" data-guest="${g.id}"><div class="guest-avatar">${esc(g.full_name.split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase())}</div><div class="guest-profile-main"><span>${esc(g.preferred_language||'—')}</span><h3>${esc(g.full_name)}</h3><p>${g.stays} ${v22('stays')}${g.next_stay?` · ${v22('nextStay')}: ${esc(g.next_stay.property_name)} ${fmtDate(g.next_stay.arrival_date)}`:''}</p><div class="guest-pref-pills">${g.preferences.slice(0,3).map(x=>`<span>${esc(x.preference_value)}</span>`).join('')}</div></div><i>→</i></button>`).join(''):`<div class="empty">${v22('noGuests')}</div>`}</section>`;
 app.innerHTML=shell(content,'guests');wireShell();document.querySelectorAll('[data-guest]').forEach(b=>b.onclick=()=>guestProfileModal(b.dataset.guest));
}

async function guestProfileModal(id){
 const d=await api(`/api/guests/${id}`),g=d.guest;
 document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="guestProfileModal"><div class="modal-card v22-modal wide-modal"><div class="modal-title"><div><span class="eyebrow">${v22('guestTitle').toUpperCase()}</span><h2>${esc(g.full_name)}</h2><p>${esc(g.preferred_language||'—')}</p></div><button class="modal-x" id="closeGuestProfile">×</button></div><div class="profile-sections"><section><span class="eyebrow">${v22('preferences').toUpperCase()}</span><div class="memory-list">${d.preferences.length?d.preferences.map(x=>`<article><b>${esc(x.preference_key.replaceAll('_',' '))}</b><span>${esc(x.preference_value)}</span><small>${esc(x.source)}</small></article>`).join(''):'<div class="empty">—</div>'}</div><button class="btn" id="addGuestPreference">+ ${v22('addPreference')}</button></section><section><span class="eyebrow">${v22('stays').toUpperCase()}</span><div class="stay-list">${d.stays.length?d.stays.map(r=>`<article><div><b>${esc(r.property_name)}</b><span>${fmtDate(r.arrival_date)} → ${fmtDate(r.departure_date)}</span></div><small>${esc(r.source)} · ${esc(r.status)}</small></article>`).join(''):'<div class="empty">—</div>'}</div></section></div></div></div>`);
 const close=()=>$('#guestProfileModal')?.remove();$('#closeGuestProfile').onclick=close;$('#guestProfileModal').onclick=e=>{if(e.target.id==='guestProfileModal')close()};$('#addGuestPreference').onclick=()=>guestPreferenceModal(id,close);
}
function guestPreferenceModal(id,closeParent){
 document.body.insertAdjacentHTML('beforeend',`<div class="modal modal-nested" id="guestPrefModal"><form class="modal-card small-modal" id="guestPrefForm"><span class="eyebrow">${v22('addPreference').toUpperCase()}</span><label>Key<input id="guestPrefKey" placeholder="e.g. pillow_preference" required></label><label>${v22('preferences')}<input id="guestPrefValue" placeholder="e.g. prefers an extra pillow" required></label><div class="modal-actions"><button type="button" class="btn" id="cancelGuestPref">${v22('close')}</button><button class="btn primary">${v22('save')}</button></div></form></div>`);
 const close=()=>$('#guestPrefModal')?.remove();$('#cancelGuestPref').onclick=close;$('#guestPrefForm').onsubmit=async e=>{e.preventDefault();await api(`/api/guests/${id}/preferences`,{method:'POST',body:JSON.stringify({preference_key:$('#guestPrefKey').value,preference_value:$('#guestPrefValue').value})});close();closeParent();guestProfileModal(id)};
}

async function ownerRegistration(){
 const items=await api('/api/registration'),ready=items.filter(x=>x.state==='ready').length,waiting=items.filter(x=>x.state==='waiting').length,needs=items.filter(x=>x.state==='needs_owner').length;
 const content=`<section class="top compact"><span class="eyebrow">VENDÉGEM PREPARATION / PILOT</span><h1>${v22('regTitle')}</h1><p>${v22('regDesc')}</p></section><div class="privacy-banner"><b>V2.2.3 SAFETY BOUNDARY</b><span>Delvane stores registration status and preparation progress here. This pilot does not add passport scans or identity-document numbers to the new cloud-shaped workflow.</span></div><section class="intel-metrics v22-metrics"><article><span>${v22('ready')}</span><strong>${ready}</strong></article><article><span>${v22('waiting')}</span><strong>${waiting}</strong></article><article><span>${v22('needsOwner')}</span><strong>${needs}</strong></article></section><section class="registration-grid">${items.map(r=>`<article class="registration-card ${r.state}"><header><div><span>${esc(r.property_name)} · ${fmtDate(r.arrival_date)}</span><h3>${esc(r.guest_name)}</h3></div><span class="state ${r.state==='ready'?'ready':'attention'}">${r.state==='ready'?v22('ready'):r.state==='needs_owner'?v22('needsOwner'):v22('waiting')}</span></header><div class="registration-progress"><div><i style="width:${Math.round((r.complete_count/Math.max(1,r.expected_count))*100)}%"></i></div><b>${r.complete_count}/${r.expected_count} ${v22('prepared')}</b></div><div class="registration-guests">${r.guests.length?r.guests.map(g=>`<div><span class="reg-dot ${g.completeness==='complete'?'done':''}"></span><b>${esc(g.full_name)}</b><small>${esc(g.nationality||'—')} · ${esc(g.completeness)}</small></div>`).join(''):`<div class="muted">${r.registration_status==='complete'?v22('ready'):v22('waiting')}</div>`}</div></article>`).join('')}</section>`;
 app.innerHTML=shell(content,'registration');wireShell();
}

