function v23(k){return (V23_I18N[uiLang]||V23_I18N.en)[k]||V23_I18N.en[k]||k}
function syncKindLabel(kind){return v23({new:'newLabel',changed:'changedLabel',cancelled:'cancelledLabel',unchanged:'unchangedLabel',conflict:'conflictLabel',ignored:'ignored'}[kind]||kind)}
function syncReason(kind){return v23({new:'reasonNew',changed:'reasonChanged',cancelled:'reasonCancelled',unchanged:'reasonUnchanged',conflict:'reasonConflict',ignored:'reasonIgnored'}[kind]||'reasonIgnored')}
function syncEventLabel(type){return ({'sandbox.ready':v23('sandboxMode'),'sync.preview':v23('syncPreview'),'sync.applied':v23('importComplete'),'sync.error':v23('feedUnavailable'),'sync.recovered':v23('recoverFeed'),'sandbox.booking.created':v23('newBooking'),'sandbox.booking.changed':v23('changedBooking'),'sandbox.ical.loaded':v23('iCalSample')}[type]||type.replaceAll('.',' · '))}
function isoPlus(days){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)}
function addIsoDays(value,days){const d=new Date(value+'T12:00:00');d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)}

async function ownerIntegrations(){
 const [items,props,summary,runs,events,government]=await Promise.all([api('/api/integrations'),api('/api/properties'),api('/api/integration-sync/summary'),api('/api/integration-sync/runs'),api('/api/integration-events'),api('/api/government/status')]);
 const bookingItems=items.filter(i=>i.provider.includes('Booking')),otherItems=items.filter(i=>!i.provider.includes('Booking')),readyCount=bookingItems.filter(i=>i.connection_stage==='channex_ready').length,activeReceivers=bookingItems.filter(i=>i.receiver_state==='active').length,activeDistribution=bookingItems.filter(i=>i.distribution_state==='active').length,waitingCount=bookingItems.length-readyCount,unacknowledged=bookingItems.reduce((n,i)=>n+(i.unacknowledged_count||0),0),ariPending=bookingItems.reduce((n,i)=>n+(i.ari_pending_count||0),0);
 const renderConnectionCard=i=>{const booking=i.provider.includes('Booking'),channexReady=i.connection_stage==='channex_ready',receiverActive=channexReady&&i.receiver_state==='active',outage=booking?channexReady&&i.status==='error':i.public_config?.sandbox_outage||i.status==='error',sandboxOnly=i.connection_stage==='sandbox_only',statusLabel=outage?'NEEDS ATTENTION':receiverActive?'RECEIVER ACTIVE':channexReady?'SETUP REQUIRED':booking?'NOT CONNECTED':'SANDBOX ONLY',statusClass=outage?'error':receiverActive?'ready':booking?'disconnected':'sandbox-only';return `<article class="sync-connection-card ${outage?'has-error':''} ${channexReady?'channex-ready':''}">
   <header><div class="sync-brand ${i.provider.includes('Booking')?'booking':'szallas'}">${esc((i.provider||'?')[0])}</div><div><span>${esc(i.property_name||'—')}</span><h3>${esc(i.provider)}</h3></div><span class="sync-status ${statusClass}"><i></i>${statusLabel}</span></header>
   ${receiverActive?`<div class="channex-ready-panel receiver-live"><b>✓ Reservation receiver is running</b><span>Delvane checks Channex automatically and routes bookings by room type to ${esc(i.property_name)}.</span></div>`:channexReady?`<div class="connection-needed-panel"><b>Receiver setup incomplete</b><span>The inventory mapping exists, but Delvane cannot contact Channex with the shared key.</span></div>`:booking?`<div class="connection-needed-panel"><b>Connection not prepared</b><span>No Channex room or rate is mapped for ${esc(i.property_name)}.</span></div>`:`<div class="connection-needed-panel neutral"><b>Test feed only</b><span>Szallas.hu production access has not been configured.</span></div>`}
   <div class="sync-card-body"><div><small>TRANSPORT</small><b>${esc(channexReady?'Two-way Channex API':sandboxOnly?'Local test feed':'None')}</b></div><div><small>${channexReady?'OUTGOING QUEUE':'TEST CHANGES'}</small><b>${channexReady?(i.ari_pending_count||0):(i.pending_count||0)}</b></div><div><small>${channexReady?'LAST DISTRIBUTION UPDATE':'LAST TEST'}</small><b>${i.last_ari_sent_at?new Date(i.last_ari_sent_at).toLocaleString(rosaLocaleCode()):v23('never')}</b></div></div>
   ${outage&&i.last_error?`<div class="sync-card-error"><b>${v23('lastError')}</b><span>${esc(i.last_error)}</span></div>`:''}
   <footer>${booking?`<button class="btn connect-booking ${channexReady?'linked':''}" data-connect-booking="${i.id}">${channexReady?'Manage inventory mapping':'Map Channex inventory'}</button>`:''}${channexReady?`<button class="btn primary manage-distribution" data-ari="${i.id}" data-property="${esc(i.property_name||'Property')}">Rates & availability</button><button class="btn receive-bookings" data-channex-receive="${i.id}" ${receiverActive?'':'disabled'}>↻ Check bookings</button><button class="btn" data-open-reservations>Reservations</button>`:`<button class="btn sync-open" data-sync-open="${i.id}">Test feed</button><button class="btn sync-now" data-sync-now="${i.id}" ${outage?'disabled':''}>Review test data</button>`}</footer>
 </article>`};
 const seenEvents=new Set(),cleanEvents=[];for(const e of events){const key=`${e.property_name}|${e.provider}|${e.event_type}`;if(!seenEvents.has(key)){seenEvents.add(key);cleanEvents.push(e)}if(cleanEvents.length===12)break}
 const history=cleanEvents.map(e=>`<article class="sync-log-row ${e.level}"><span class="sync-log-dot"></span><div><b>${esc(e.property_name||'—')} · ${esc(e.provider)}</b><p>${esc(syncEventLabel(e.event_type))}</p></div><time>${new Date(e.created_at).toLocaleString(rosaLocaleCode())}</time></article>`).join('');
 const content=`<section class="top compact sync-hero"><span class="eyebrow">V2.10.28 · ${tr('integrations').toUpperCase()}</span><h1>Channel distribution</h1><p>Base prices and availability stay published automatically, while reservations and date-specific overrides update Channex safely.</p></section>
 <section class="connection-phase-banner"><div><span class="eyebrow">CURRENT PHASE</span><h2>Two-way channel control</h2><p>Changes made in Delvane are saved first, queued durably, batched by date range and retried automatically if Channex is temporarily unavailable.</p></div><div class="connection-phase-grid five"><article class="done"><i>1</i><b>Shared API</b><span>Connected</span></article><article class="${readyCount?'done':'current'}"><i>2</i><b>Mapping</b><span>${readyCount}/${bookingItems.length}</span></article><article class="${activeReceivers?'done':'current'}"><i>3</i><b>Bookings</b><span>${activeReceivers} active</span></article><article class="${activeDistribution?'done':'current'}"><i>4</i><b>Distribution</b><span>${activeDistribution} active</span></article><article class="current"><i>5</i><b>Certification</b><span>Next</span></article></div></section>
 <section class="connection-summary-grid"><article class="success"><span>ACTIVE DISTRIBUTION</span><strong>${activeDistribution}</strong><small>Properties ready for outbound updates</small></article><article><span>OUTGOING QUEUE</span><strong>${ariPending}</strong><small>Saved changes awaiting delivery</small></article><article><span>UNACKNOWLEDGED BOOKINGS</span><strong>${unacknowledged}</strong><small>Incoming revisions awaiting confirmation</small></article><article><span>STILL DISCONNECTED</span><strong>${waitingCount}</strong><small>Booking.com apartments needing preparation</small></article></section>
 <div class="section-head connection-section-head"><div><span class="eyebrow">BOOKING.COM</span><h2>Booking.com connections</h2></div><button class="btn" id="addIntegration">+ ${v22('addConnection')}</button></div>
 <section class="sync-connection-grid">${bookingItems.map(renderConnectionCard).join('')}</section>
 <div class="section-head connection-section-head secondary"><div><span class="eyebrow">OTHER CHANNELS</span><h2>Szallas.hu and test feeds</h2></div></div>
 <section class="sync-connection-grid">${otherItems.map(renderConnectionCard).join('')}</section>
 <div class="sync-safety-banner government-note"><span>↗</span><div><b>HUNGARIAN GOVERNMENT REPORTING</b><p>${government.rosa_mtu_certified?'Delvane certification is enabled; configured properties can submit automatically.':'NTAK and VIZA transmission remains locked until MTÜ certifies commercial Delvane. Reservation reports stay queued safely.'}</p></div></div>
 <section class="sync-history-panel"><div class="section-head"><div><span class="eyebrow">${v23('history').toUpperCase()}</span><h2>${v23('history')}</h2></div></div><div class="sync-log">${history||`<div class="empty">${v23('noHistory')}</div>`}</div></section>`;
 app.innerHTML=shell(content,'integrations');wireShell();
 $('#addIntegration').onclick=()=>integrationSlotModal(props);
 document.querySelectorAll('[data-connect-booking]').forEach(b=>b.onclick=()=>channexInventoryMappingModal(b.dataset.connectBooking));
 document.querySelectorAll('[data-ari]').forEach(b=>b.onclick=()=>channelDistributionModal(b.dataset.ari,b.dataset.property));
 document.querySelectorAll('[data-channex-receive]').forEach(b=>b.onclick=()=>receiveChannexBookings(b));
 document.querySelectorAll('[data-open-reservations]').forEach(b=>b.onclick=()=>navigate('reservations'));
 document.querySelectorAll('[data-sync-open]').forEach(b=>b.onclick=()=>integrationSandboxModal(b.dataset.syncOpen));
 document.querySelectorAll('[data-sync-now]').forEach(b=>b.onclick=()=>runSyncPreview(b.dataset.syncNow));
}

async function channelDistributionModal(id,propertyName){
 const start=isoPlus(7),end=isoPlus(13),data=await api(`/api/integrations/${id}/channex/ari?date_from=${start}&date_to=${end}`),mappings=await api(`/api/integrations/${id}/channex/rate-mappings`),pending=(data.outbox?.queued||0)+(data.outbox?.retry||0)+(data.outbox?.sending||0);
 const currency=String(data.currency||'HUF').toUpperCase(), priceStep=currency==='HUF'?'1':'0.01';
 const rateOptions=mappings.map(m=>`<option value="${esc(m.rate_plan_id)}">${esc(m.room_type_name||'Room type')} · ${esc(m.rate_plan_name)} · ${esc(m.channex_rate_plan_id)}</option>`).join('');
 document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="ariModal"><form class="modal-card ari-modal-card" id="ariForm"><div class="modal-title"><div><span class="eyebrow">CHANNEL DISTRIBUTION · CHANNEX</span><h2>${esc(propertyName)}</h2><p>Change a date or range once. Delvane saves it locally and sends one batched update per Channex endpoint.</p></div><button type="button" class="modal-x" id="closeAri">×</button></div>
 <div class="ari-health"><div><span>OUTGOING QUEUE</span><b>${pending}</b></div><div><span>CONFIGURED DAYS</span><b>${data.values?.length||0}</b></div><div><span>LAST DELIVERED</span><b>${data.last_sent_at?new Date(data.last_sent_at).toLocaleString(rosaLocaleCode()):'Never'}</b></div></div>
 <section class="ari-queue-panel" id="ariQueuePanel"><div class="ari-queue-head"><div><span class="eyebrow">DELIVERY DIAGNOSTICS</span><h3>Channex delivery queue</h3><p>See pending requests, retry timing and the last provider error. No credentials or payload data are shown.</p></div><button type="button" class="btn" id="refreshAriQueue">Refresh queue</button></div><div id="ariQueueBody"><div class="muted">Loading queue status…</div></div><div class="ari-queue-actions"><button type="button" class="btn primary" id="retryAriQueue">Retry pending now</button></div></section>
 <section class="base-rate-card"><div><span class="eyebrow">DEFAULT CALENDAR PRICE</span><h3>Base nightly price</h3><p>Publish one normal price for the next 365 days. Existing date-specific prices remain overrides, and Delvane extends the calendar automatically.</p></div><label>${currency} per night<input id="ariBaseRate" type="number" min="1" step="${priceStep}" value="${data.base_rate?.base_nightly_rate_huf||''}" placeholder="e.g. 42000"></label><button type="button" class="btn primary" id="saveBaseRate">${data.base_rate?'Update & republish':'Set & publish 365 days'}</button></section>
 <div class="ari-section-label"><span>DATE-SPECIFIC OVERRIDES</span><p>Use these controls only when selected dates should differ from the base calendar.</p></div>
 <section class="base-rate-card full-sync-card"><div><span class="eyebrow">CHANNEX CERTIFICATION</span><h3>500-day full sync</h3><p>Send the complete 500-day availability and rates/restrictions state in the two API calls required for Channex certification.</p></div><button type="button" class="btn" id="runChannexFullSync">Run 500-day full sync</button></section>
 <div class="ari-date-row"><label>From<input id="ariFrom" type="date" min="${isoPlus(0)}" value="${start}" required></label><label>To<input id="ariTo" type="date" min="${isoPlus(0)}" value="${end}" required></label></div>
 <div class="ari-control-grid"><label>Room type<select id="ariRoomType"><option value="">Default room type</option></select></label><label>Rate plan<select id="ariRatePlan">${rateOptions}</select></label><label>Nightly price <small>${currency}</small><input id="ariRate" type="number" min="1" step="${priceStep}" placeholder="Keep current"></label><label>Availability <small>available units</small><input id="ariAvailability" type="number" min="0" step="1" placeholder="Keep current"></label>${data.certification_workspace?`<label class="ari-force-availability"><span>Certification resend</span><span><input id="ariForceAvailability" type="checkbox" checked> Resend even when unchanged</span></label>`:""}<label>Min stay · arrival <small>nights</small><input id="ariMinStayArrival" type="number" min="1" max="365" placeholder="Keep current"></label><label>Min stay · through <small>nights</small><input id="ariMinStayThrough" type="number" min="1" max="365" placeholder="Keep current"></label><label>Max stay <small>nights · 0 = off</small><input id="ariMaxStay" type="number" min="0" max="365" placeholder="Keep current"></label><label>Stop sell<select id="ariStopSell"><option value="">Keep current</option><option value="false">Off · sell normally</option><option value="true">On · stop selling</option></select></label><label>Closed to arrival<select id="ariCta"><option value="">Keep current</option><option value="false">No</option><option value="true">Yes</option></select></label><label>Closed to departure<select id="ariCtd"><option value="">Keep current</option><option value="false">No</option><option value="true">Yes</option></select></label></div>
 <section class="ari-bulk-card"><div class="ari-bulk-head"><div><span class="eyebrow">RATE PLAN UPDATES</span><h3>Bulk rate & restriction changes</h3><p>Update several rate plans in one Channex request. Add only the rows you need.</p></div><div class="ari-bulk-help"><b>How it works</b><span>Choose a rate plan, set its dates, then change only the fields you want to send.</span></div></div><div class="ari-bulk-toolbar"><span class="ari-bulk-count" id="ariBulkCount">1 rate plan</span><button type="button" class="btn" id="addAriBulkRow" ${rateOptions?'':'disabled'}>+ Add rate plan</button></div><div id="ariBulkRows">${rateOptions?`<div class="ari-bulk-row"><div class="ari-bulk-row-top"><label><span>Rate plan</span><select class="ariBulkPlan">${rateOptions}</select></label><button type="button" class="ari-bulk-remove" title="Remove rate plan" aria-label="Remove rate plan">×</button></div><div class="ari-bulk-fields"><label><span>From</span><input class="ariBulkFrom" type="date" value="${start}" min="${isoPlus(0)}"></label><label><span>To</span><input class="ariBulkTo" type="date" value="${end}" min="${isoPlus(0)}"></label><label><span>Nightly price <small>${currency}</small></span><input class="ariBulkRate" type="number" min="1" step="${priceStep}" placeholder="Keep current"></label><label><span>Min stay · arrival <small>nights</small></span><input class="ariBulkMinArrival" type="number" min="1" max="365" placeholder="Keep current"></label><label><span>Min stay · through <small>nights</small></span><input class="ariBulkMinThrough" type="number" min="1" max="365" placeholder="Keep current"></label><label><span>Max stay <small>nights · 0 = off</small></span><input class="ariBulkMax" type="number" min="0" max="365" placeholder="Keep current"></label></div><div class="ari-bulk-restrictions"><span class="ari-bulk-subtitle">Restrictions</span><label><span>Stop sell</span><select class="ariBulkStop"><option value="">Keep current</option><option value="false">Off · sell normally</option><option value="true">On · stop selling</option></select></label><label><span>Closed to arrival</span><select class="ariBulkCta"><option value="">Keep current</option><option value="false">No</option><option value="true">Yes</option></select></label><label><span>Closed to departure</span><select class="ariBulkCtd"><option value="">Keep current</option><option value="false">No</option><option value="true">Yes</option></select></label></div></div>`:'<div class="muted">No Channex rate-plan mappings are available yet.</div>'}</div><div class="ari-bulk-note"><span>ⓘ</span><div><b>Only changed fields are sent.</b><span>“Keep current” leaves that value untouched. All rows are sent together in one Channex restrictions request.</span></div></div><p class="form-error" id="ariBulkError"></p><div class="ari-bulk-actions"><button type="button" class="btn primary" id="saveAriBulk" ${rateOptions?'':'disabled'}>Save & send bulk updates</button></div></section>
 <div class="safe-field ari-safe"><b>Durable delivery</b><span>If Channex is unavailable, the change remains saved in Delvane and retries automatically with backoff. Shared credentials stay hidden.</span></div><p class="form-error" id="ariError"></p><div class="modal-actions"><button type="button" class="btn" id="cancelAri">Cancel</button><button class="btn primary" id="saveAri">Save & send</button></div></form></div>`);
 const close=()=>$('#ariModal')?.remove();$('#closeAri').onclick=close;$('#cancelAri').onclick=close;
 const renderAriQueue=queue=>{const body=$('#ariQueueBody');if(!body)return;const items=queue.items||[];if(!items.length){body.innerHTML='<div class="ari-queue-empty">Queue is clear — no pending Channex ARI requests.</div>';return}body.innerHTML=items.map(item=>{const retry=item.status==='retry';const due=item.retry_due;const wait=item.seconds_until_retry||0;const waitText=due?'Eligible now':`Retry in ${Math.ceil(wait/60)} min`;return `<div class="ari-queue-row"><div><b>${esc(item.endpoint_label)}</b><span>${esc(item.status)} · attempt ${Number(item.attempts||0)}</span></div><div><span>${esc(waitText)}</span><small>${esc(item.available_at||'')}</small></div><div class="ari-queue-error">${item.last_error?`<b>Last error</b><span>${esc(item.last_error)}</span>`:'<span>No provider error recorded.</span>'}</div></div>`}).join('')};
 const loadAriQueue=async()=>{try{const q=await api(`/api/integrations/${id}/channex/outbox`);renderAriQueue(q)}catch(err){$('#ariQueueBody').innerHTML=`<div class="form-error">${esc(err.message)}</div>`}};
 $('#refreshAriQueue').onclick=loadAriQueue;
 $('#retryAriQueue').onclick=async()=>{const button=$('#retryAriQueue');button.disabled=true;button.textContent='Retrying…';try{const out=await api(`/api/integrations/${id}/channex/outbox/retry`,{method:'POST'});renderAriQueue(out.queue);const failed=out.delivery?.failed||[];if(failed.length){$('#ariError').textContent=failed.map(x=>x.error).join(' · ')}else{$('#ariError').textContent=out.delivery?.delivered?.length?`${out.delivery.delivered.length} pending request${out.delivery.delivered.length===1?'':'s'} delivered.`:'No pending requests needed delivery.'}}catch(err){$('#ariError').textContent=err.message}finally{button.disabled=false;button.textContent='Retry pending now'}};
 loadAriQueue();
 const roomTypes=(data.room_types||[]);
 $('#ariRoomType').innerHTML='<option value="">Default room type</option><option value="__all__">All mapped room types</option>'+roomTypes.map(rt=>`<option value="${rt.id}">${esc(rt.name)} · ${rt.inventory_count} unit${rt.inventory_count===1?'':'s'}</option>`).join('');
 const numberOrNull=selector=>{const value=$(selector).value.trim();return value===''?null:Number(value)};
 $('#runChannexFullSync').onclick=async()=>{const button=$('#runChannexFullSync');button.disabled=true;button.textContent='Running 500-day sync…';$('#ariError').textContent='';try{const out=await api(`/api/integrations/${id}/channex/full-sync`,{method:'POST'});close();channelDistributionResult(out,propertyName)}catch(err){$('#ariError').textContent=err.message;button.disabled=false;button.textContent='Run 500-day full sync'}};
 const boolOrNull=selector=>{const value=$(selector).value;return value===''?null:value==='true'};
 $('#saveBaseRate').onclick=async()=>{const value=numberOrNull('#ariBaseRate'),button=$('#saveBaseRate');if(!value||value<=0){$('#ariError').textContent='Enter a base nightly price greater than zero.';return}button.disabled=true;button.textContent='Publishing 365 days…';$('#ariError').textContent='';try{const out=await api(`/api/integrations/${id}/channex/base-rate`,{method:'PUT',body:JSON.stringify({base_rate_huf:value,horizon_days:365})});close();channelDistributionResult(out,propertyName)}catch(err){$('#ariError').textContent=err.message;button.disabled=false;button.textContent=data.base_rate?'Update & republish':'Set & publish 365 days'}};
 const bulkRowMarkup=()=>`<div class="ari-bulk-row"><div class="ari-bulk-row-top"><label><span>Rate plan</span><select class="ariBulkPlan">${rateOptions}</select></label><button type="button" class="ari-bulk-remove" title="Remove rate plan" aria-label="Remove rate plan">×</button></div><div class="ari-bulk-fields"><label><span>From</span><input class="ariBulkFrom" type="date" value="${start}" min="${isoPlus(0)}"></label><label><span>To</span><input class="ariBulkTo" type="date" value="${end}" min="${isoPlus(0)}"></label><label><span>Nightly price <small>${currency}</small></span><input class="ariBulkRate" type="number" min="1" step="${priceStep}" placeholder="Keep current"></label><label><span>Min stay · arrival <small>nights</small></span><input class="ariBulkMinArrival" type="number" min="1" max="365" placeholder="Keep current"></label><label><span>Min stay · through <small>nights</small></span><input class="ariBulkMinThrough" type="number" min="1" max="365" placeholder="Keep current"></label><label><span>Max stay <small>nights · 0 = off</small></span><input class="ariBulkMax" type="number" min="0" max="365" placeholder="Keep current"></label></div><div class="ari-bulk-restrictions"><span class="ari-bulk-subtitle">Restrictions</span><label><span>Stop sell</span><select class="ariBulkStop"><option value="">Keep current</option><option value="false">Off · sell normally</option><option value="true">On · stop selling</option></select></label><label><span>Closed to arrival</span><select class="ariBulkCta"><option value="">Keep current</option><option value="false">No</option><option value="true">Yes</option></select></label><label><span>Closed to departure</span><select class="ariBulkCtd"><option value="">Keep current</option><option value="false">No</option><option value="true">Yes</option></select></label></div></div>`;
 const refreshBulkUI=()=>{const rows=[...document.querySelectorAll('#ariBulkRows .ari-bulk-row')],count=$('#ariBulkCount');if(count)count.textContent=`${rows.length} rate plan${rows.length===1?'':'s'}`;rows.forEach((row,i)=>{const remove=row.querySelector('.ari-bulk-remove');if(remove)remove.disabled=rows.length===1})};
 $('#ariBulkRows').onclick=e=>{const remove=e.target.closest('.ari-bulk-remove');if(!remove)return;remove.closest('.ari-bulk-row')?.remove();refreshBulkUI()};
 $('#addAriBulkRow').onclick=()=>{$('#ariBulkRows').insertAdjacentHTML('beforeend',bulkRowMarkup());refreshBulkUI();document.querySelectorAll('#ariBulkRows .ari-bulk-row').at(-1)?.scrollIntoView({block:'nearest',behavior:'smooth'})};
 refreshBulkUI();
 $('#saveAriBulk').onclick=async()=>{const button=$('#saveAriBulk'),error=$('#ariBulkError');error.textContent='';const rows=[...document.querySelectorAll('#ariBulkRows .ari-bulk-row')],seen=new Set(),updates=[];for(const row of rows){const v=s=>row.querySelector(s)?.value?.trim()||'';const b=s=>{const x=v(s);return x===''?null:x==='true'};const n=s=>{const x=v(s);return x===''?null:Number(x)};const plan=v('.ariBulkPlan'),from=v('.ariBulkFrom'),to=v('.ariBulkTo'),rate=n('.ariBulkRate'),minArrival=n('.ariBulkMinArrival'),minThrough=n('.ariBulkMinThrough'),maxStay=n('.ariBulkMax'),stop=b('.ariBulkStop'),cta=b('.ariBulkCta'),ctd=b('.ariBulkCtd');if(!plan||!from||!to){error.textContent='Complete the rate plan and date range for every row.';return}if(from>to){error.textContent='The “From” date cannot be after the “To” date.';return}if(seen.has(plan)){error.textContent='Each rate plan can appear only once in this update.';return}seen.add(plan);if(rate===null&&minArrival===null&&minThrough===null&&maxStay===null&&stop===null&&cta===null&&ctd===null){error.textContent='Change at least one value in every row, or remove that row.';return}updates.push({rate_plan_id:plan,date_from:from,date_to:to,rate_huf:rate,min_stay_arrival:minArrival,min_stay_through:minThrough,max_stay:maxStay,stop_sell:stop,closed_to_arrival:cta,closed_to_departure:ctd})}button.disabled=true;button.textContent='Sending bulk updates…';try{const out=await api(`/api/integrations/${id}/channex/ari/batch`,{method:'PUT',body:JSON.stringify({updates})});close();channelDistributionResult(out,propertyName)}catch(err){error.textContent=err.message;button.disabled=false;button.textContent='Save & send bulk updates'}};
 $('#ariForm').onsubmit=async e=>{e.preventDefault();const button=$('#saveAri');button.disabled=true;button.textContent='Saving…';try{const out=await api(`/api/integrations/${id}/channex/ari`,{method:'PUT',body:JSON.stringify({date_from:$('#ariFrom').value,date_to:$('#ariTo').value,room_type_id:$('#ariRoomType').value||null,rate_plan_id:$('#ariRatePlan').value||null,rate_huf:numberOrNull('#ariRate'),availability:numberOrNull('#ariAvailability'),min_stay_arrival:numberOrNull('#ariMinStayArrival'),min_stay_through:numberOrNull('#ariMinStayThrough'),max_stay:numberOrNull('#ariMaxStay'),stop_sell:boolOrNull('#ariStopSell'),closed_to_arrival:boolOrNull('#ariCta'),closed_to_departure:boolOrNull('#ariCtd'),force_availability:Boolean($('#ariForceAvailability')?.checked)})});close();channelDistributionResult(out,propertyName)}catch(err){$('#ariError').textContent=err.message;button.disabled=false;button.textContent='Save & send'}};
}

function channelDistributionResult(out,propertyName){
 const delivered=out.delivery?.delivered||[],failed=out.delivery?.failed||[];
 const total=Number(out.queued||delivered.length+failed.length);
 const noChange=Boolean(out.no_change);
 const pending=!noChange && !failed.length && delivered.length===0 && total>0;
 const summary=failed.length?`${delivered.length} of ${total} requests delivered · ${failed.length} queued for automatic retry`:pending?`0 of ${total} requests delivered · waiting for delivery` :noChange?'0 requests sent':`${delivered.length} of ${total} requests delivered`;
 const title=noChange?'No update sent':failed.length?'Saved; delivery will retry':pending?'Update queued':'Update delivered';
 document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="ariResultModal"><div class="modal-card receiver-result-card"><div class="connection-success-mark">${failed.length?'↻':noChange?'i':'✓'}</div><span class="eyebrow">CHANNEL DISTRIBUTION</span><h2>${title}</h2><p>${esc(propertyName)} · ${out.days} day${out.days===1?'':'s'} · ${summary}</p>${noChange?`<div class="sync-card-error"><b>Nothing changed</b><span>${esc(out.message||'The selected value already matches Delvane’s current state.')}</span></div>`:failed.length?`<div class="sync-card-error"><b>No data was lost</b><span>The remaining update is safely stored in Delvane. It will retry automatically; you do not need to enter it again.</span><details><summary>Technical details</summary><small>${esc(failed.map(x=>x.error).join(' · '))}</small></details></div>`:pending?`<div class="sync-card-error"><b>Saved safely</b><span>The update is in Delvane’s durable outbox and will be delivered automatically. No Channex task ID exists yet, so do not submit this run as certified until delivery completes.</span></div>`:`<div class="ari-task-list">${delivered.map(x=>`<div><span>${esc(x.endpoint.endsWith('availability')?'Availability':'Rates & restrictions')}</span><b>${esc((x.task_ids||[]).join(', ')||'Accepted')}</b></div>`).join('')}</div>`}<div class="modal-actions"><button class="btn primary" id="ariResultDone">Done</button></div></div></div>`);
 $('#ariResultDone').onclick=()=>{$('#ariResultModal')?.remove();ownerIntegrations()};
}

async function receiveChannexBookings(button){
 const original=button.textContent;button.disabled=true;button.textContent='Checking Channex…';
 try{
  const out=await api(`/api/integrations/${button.dataset.channexReceive}/channex/receive`,{method:'POST'}),c=out.counts||{};
  const rows=(out.reservations||[]).map(x=>`<article class="receiver-result-row"><span class="change-kind">${esc((x.kind||'saved').toUpperCase())}</span><div><b>${esc(x.property_name)} · ${esc(x.external_ref)}</b><small>${x.acknowledged?'Saved and acknowledged':'Saved; acknowledgement will retry automatically'}</small></div></article>`).join('');
  document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="receiverResultModal"><div class="modal-card receiver-result-card"><div class="connection-success-mark">${out.ok?'✓':'!'}</div><span class="eyebrow">CHANNEX RESERVATION RECEIVER</span><h2>${out.fetched?`${out.fetched} revision${out.fetched===1?'':'s'} checked`:'Everything is caught up'}</h2><p>${out.fetched?`${c.new||0} new · ${c.changed||0} modified · ${c.cancelled||0} cancelled · ${c.acknowledged||0} acknowledged`:'There are no unacknowledged booking revisions waiting in Channex.'}</p><div class="receiver-result-list">${rows}</div>${(out.errors||[]).length?`<div class="sync-card-error"><b>Needs review</b><span>${esc(out.errors.map(x=>x.error).join(' · '))}</span></div>`:''}<div class="modal-actions"><button class="btn" id="receiverOpenReservations">Open reservations</button><button class="btn primary" id="receiverDone">Done</button></div></div></div>`);
  $('#receiverDone').onclick=()=>{$('#receiverResultModal')?.remove();ownerIntegrations()};$('#receiverOpenReservations').onclick=()=>{$('#receiverResultModal')?.remove();navigate('reservations')};
 }catch(err){alert(err.message);button.disabled=false;button.textContent=original}
}

async function channexInventoryMappingModal(id){
 let data;try{data=await api(`/api/integrations/${id}/channex/inventory-mapping`)}catch(err){alert(err.message);return}
 const propertyOptions=(data.properties||[]).map(p=>`<option value="${esc(p.id)}" ${p.id===data.selected_channex_property_id?'selected':''}>${esc(p.title)}</option>`).join('');
 document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="channexMappingModal"><div class="modal-card" style="max-width:920px"><div class="modal-title"><div><span class="eyebrow">BOOKING.COM · CHANNEX</span><h2>Map existing inventory</h2><p>Delvane will only map existing Channex rooms and rate plans. It will not create anything in Channex.</p></div><button type="button" class="modal-x" id="closeChannexMapping">×</button></div><label>Channex property<select id="mapChannexProperty"><option value="">Choose…</option>${propertyOptions}</select></label><div id="channexMappingBody" style="margin-top:18px"></div><p class="form-error" id="channexMappingError"></p><div class="modal-actions"><button type="button" class="btn" id="cancelChannexMapping">Cancel</button><button type="button" class="btn primary" id="saveChannexMapping">Save mapping</button></div></div></div>`);
 const close=()=>$('#channexMappingModal')?.remove();$('#closeChannexMapping').onclick=close;$('#cancelChannexMapping').onclick=close;
 const body=$('#channexMappingBody'), error=$('#channexMappingError');
 const render=async propertyId=>{
  error.textContent='';body.innerHTML='<div class="safe-field"><b>Loading Channex inventory…</b><span>Reading existing room types and rate plans. Nothing will be changed.</span></div>';
  try{
   const d=await api(`/api/integrations/${id}/channex/inventory-mapping?channex_property_id=${encodeURIComponent(propertyId)}`);
   data=d;
   const roomMap=new Map((d.room_mappings||[]).map(x=>[x.room_type_id,x.channex_room_type_id]));
   const rateMap=new Map((d.rate_mappings||[]).map(x=>[x.rate_plan_id,x]));
   const rooms=d.remote_room_types||[],rates=d.remote_rate_plans||[];
   const roomSelect=(local,selected)=>`<select class="map-room" data-local-room="${esc(local.id)}"><option value="">Choose Channex room…</option>${rooms.map(r=>`<option value="${esc(r.id)}" ${r.id===selected?'selected':''}>${esc(r.title)} · ${r.count_of_rooms??'?'} unit${Number(r.count_of_rooms)===1?'':'s'}</option>`).join('')}</select>`;
   const rateRows=(localRoomId)=>{const locals=(d.local_rate_plans||[]).filter(r=>String(r.room_type_id||'')===String(localRoomId)&&r.active);return locals.map(r=>{const old=rateMap.get(r.id);const selected=old?.channex_rate_plan_id||'';const available=rates.filter(x=>x.room_type_id===old?.channex_room_type_id||x.room_type_id===roomMap.get(localRoomId));return `<div class="map-rate-row"><span><b>${esc(r.name)}</b><small>${esc(r.meal_type||'none')}</small></span><select class="map-rate" data-local-rate="${esc(r.id)}" data-local-room="${esc(localRoomId)}"><option value="">Choose Channex rate…</option>${available.map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div>`}).join('')||'<div class="muted">No active rate plans on this Delvane room type.</div>'};
   body.innerHTML=`<div class="safe-field"><b>${esc(d.selected_channex_property_title||'Channex property')}</b><span>${rooms.length} existing room type${rooms.length===1?'':'s'} · ${rates.length} existing rate plan${rates.length===1?'':'s'}</span></div><div class="channex-map-list">${(d.local_room_types||[]).filter(r=>r.active).map(r=>`<section class="channex-map-room"><div class="section-head"><div><span class="eyebrow">ROSA ROOM TYPE</span><h3>${esc(r.name)}</h3><p>${r.inventory_count} unit${r.inventory_count===1?'':'s'} · up to ${r.max_guests} guests</p></div>${roomSelect(r,roomMap.get(r.id))}</div><div class="channex-map-rates">${rateRows(r.id)}</div></section>`).join('')}</div>`;
   document.querySelectorAll('.map-room').forEach(sel=>sel.onchange=()=>{const local=sel.dataset.localRoom;const roomId=sel.value;document.querySelectorAll(`.map-rate[data-local-room="${CSS.escape(local)}"]`).forEach(rateSel=>{const current=rateSel.value;const opts=rates.filter(x=>x.room_type_id===roomId).map(x=>`<option value="${esc(x.id)}">${esc(x.title)}</option>`).join('');rateSel.innerHTML='<option value="">Choose Channex rate…</option>'+opts;if([...rateSel.options].some(o=>o.value===current))rateSel.value=current})});
  }catch(err){body.innerHTML='';error.textContent=err.message}
 };
 $('#mapChannexProperty').onchange=()=>render($('#mapChannexProperty').value);
 if($('#mapChannexProperty').value) await render($('#mapChannexProperty').value);
 $('#saveChannexMapping').onclick=async()=>{
  error.textContent='';const propertyId=$('#mapChannexProperty').value;if(!propertyId){error.textContent='Choose a Channex property.';return}
  const room_mappings=[...document.querySelectorAll('.map-room')].map(x=>({room_type_id:x.dataset.localRoom,channex_room_type_id:x.value})).filter(x=>x.channex_room_type_id);
  const rate_mappings=[...document.querySelectorAll('.map-rate')].map(x=>({rate_plan_id:x.dataset.localRate,channex_room_type_id:document.querySelector(`.map-room[data-local-room="${CSS.escape(x.dataset.localRoom)}"]`)?.value||'',channex_rate_plan_id:x.value})).filter(x=>x.channex_rate_plan_id);
  const localRooms=(data.local_room_types||[]).filter(x=>x.active),localRates=(data.local_rate_plans||[]).filter(x=>x.active);const roomIds=new Set(room_mappings.map(x=>x.room_type_id)),rateIds=new Set(rate_mappings.map(x=>x.rate_plan_id));
  if(roomIds.size!==localRooms.length){error.textContent='Map every active Delvane room type before saving.';return}if(rateIds.size!==localRates.length){error.textContent='Map every active Delvane rate plan before saving.';return}
  const button=$('#saveChannexMapping');button.disabled=true;button.textContent='Saving mapping…';try{const out=await api(`/api/integrations/${id}/channex/inventory-mapping`,{method:'PUT',body:JSON.stringify({channex_property_id:propertyId,room_mappings,rate_mappings})});close();await ownerIntegrations();alert(`Mapping saved: ${out.room_count} room types and ${out.rate_count} rate plans. No Channex inventory was created.`)}catch(err){error.textContent=err.message;button.disabled=false;button.textContent='Save mapping'}
 };
}


function integrationSlotModal(props){
 document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="integrationModal"><form class="modal-card" id="integrationForm"><div class="modal-title"><div><span class="eyebrow">${v22('addConnection').toUpperCase()}</span><h2>${v23('syncSandbox')}</h2></div><button type="button" class="modal-x" id="closeIntegration">×</button></div><label>${v22('property')}<select id="intProperty" required><option value="">—</option>${props.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label>${v22('provider')}<select id="intProvider"><option>Booking.com</option><option>Szallas.hu</option><option>Other</option></select></label><label>${v22('connectionType')}<input id="intType" value="calendar feed / future API"></label><div class="safe-field"><b>${v23('localSandbox')}</b><span>${v23('noRealSecrets')}</span></div><div class="modal-actions"><button type="button" class="btn" id="cancelIntegration">${v22('close')}</button><button class="btn primary">${v22('saveSlot')}</button></div></form></div>`);
 const close=()=>$('#integrationModal')?.remove();$('#closeIntegration').onclick=close;$('#cancelIntegration').onclick=close;$('#integrationForm').onsubmit=async e=>{e.preventDefault();await api('/api/integrations',{method:'POST',body:JSON.stringify({property_id:$('#intProperty').value,provider:$('#intProvider').value,connection_type:$('#intType').value})});close();ownerIntegrations()};
}

async function integrationSandboxModal(id){
 const data=await api(`/api/integrations/${id}/feed`),i=data.integration,outage=i.public_config?.sandbox_outage;
 const itemRows=data.items.map(x=>`<article class="sandbox-feed-row ${x.status}"><div class="feed-state-dot"></div><div class="feed-main"><span>${esc(x.external_ref)}</span><h4>${esc(x.guest_name)}</h4><p>${fmtDate(x.arrival_date)} → ${fmtDate(x.departure_date)} · ${x.guest_count} ${v23('guestCount').toLowerCase()}</p></div><span class="feed-status">${x.status==='cancelled'?v23('cancelled'):v23('active')}</span><div class="feed-actions"><button type="button" data-feed-extend="${esc(x.external_ref)}" data-dep="${x.departure_date}" ${x.status==='cancelled'?'disabled':''}>${v23('extendNight')}</button><button type="button" data-feed-toggle="${esc(x.external_ref)}" data-status="${x.status}">${x.status==='cancelled'?v23('restoreFeedItem'):v23('cancelFeedItem')}</button></div></article>`).join('');
 document.body.insertAdjacentHTML('beforeend',`<div class="modal sync-sandbox-modal" id="syncSandboxModal"><div class="modal-card sync-sandbox-card"><div class="modal-title"><div><span class="eyebrow">${v23('sandboxMode')}</span><h2>${esc(i.property_name)} · ${esc(i.provider)}</h2><p>iCal / API</p></div><button type="button" class="modal-x" id="closeSandbox">×</button></div>
 <div class="sandbox-toolbar"><div class="sandbox-health ${outage?'error':'ok'}"><i></i><div><b>${outage?v23('feedUnavailable'):v23('syncSuccess')}</b><span>${outage?esc(i.last_error||v23('feedOutage')):v23('actionsSafe')}</span></div></div><div>${outage?`<button class="btn primary" id="recoverFeed">${v23('recoverFeed')}</button>`:`<button class="btn" id="simulateOutage">${v23('simulateOutage')}</button>`}<button class="btn primary" id="sandboxSync" ${outage?'disabled':''}>↻ ${v23('syncNow')}</button></div></div>
 <div class="sandbox-columns"><section class="sandbox-feed-panel"><div class="section-head"><div><span class="eyebrow">${v23('currentFeed').toUpperCase()}</span><h3>${v23('currentFeed')}</h3></div><span class="count-pill">${data.items.length}</span></div><div class="sandbox-feed-list">${itemRows||'<div class="empty">—</div>'}</div></section>
 <section class="sandbox-simulator"><span class="eyebrow">${v23('testScenarios').toUpperCase()}</span><h3>${v23('simulateBooking')}</h3><form id="sandboxBookingForm" class="sandbox-booking-form"><label>${v23('guestName')}<input id="sbxGuest" value="Sandbox Guest" required></label><div class="form-two"><label>${v23('arrival')}<input id="sbxArrival" type="date" value="${isoPlus(35)}" required></label><label>${v23('departure')}<input id="sbxDeparture" type="date" value="${isoPlus(38)}" required></label></div><div class="form-two"><label>${v23('guestCount')}<input id="sbxGuests" type="number" min="1" max="10" value="2" required></label><label>${v23('externalRef')}<input id="sbxRef" placeholder="auto"></label></div><button class="btn primary wide-btn">+ ${v23('addToFeed')}</button></form>
 <details class="ical-test"><summary>${v23('iCalSample')}</summary><p>${v23('iCalDesc')}</p><textarea id="icalSample" rows="6" placeholder="BEGIN:VCALENDAR\nBEGIN:VEVENT\nUID:sample-1\nDTSTART;VALUE=DATE:20261020\nDTEND;VALUE=DATE:20261023\nSUMMARY:Sample Guest\nEND:VEVENT\nEND:VCALENDAR"></textarea><label class="check-row"><input type="checkbox" id="replaceIcal"><span>${v23('replaceFeed')}</span></label><button type="button" class="btn" id="loadIcal">${v23('loadIcal')}</button></details></section></div></div></div>`);
 const close=()=>$('#syncSandboxModal')?.remove();$('#closeSandbox').onclick=close;$('#syncSandboxModal').onclick=e=>{if(e.target.id==='syncSandboxModal')close()};
 $('#sandboxSync').onclick=()=>{close();runSyncPreview(id)};
 $('#simulateOutage')?.addEventListener('click',async()=>{await api(`/api/integrations/${id}/sandbox/outage`,{method:'POST'});close();integrationSandboxModal(id)});
 $('#recoverFeed')?.addEventListener('click',async()=>{await api(`/api/integrations/${id}/sandbox/recover`,{method:'POST'});close();integrationSandboxModal(id)});
 $('#sandboxBookingForm').onsubmit=async e=>{e.preventDefault();await api(`/api/integrations/${id}/sandbox/events`,{method:'POST',body:JSON.stringify({external_ref:$('#sbxRef').value.trim()||null,guest_name:$('#sbxGuest').value,arrival_date:$('#sbxArrival').value,departure_date:$('#sbxDeparture').value,guest_count:Number($('#sbxGuests').value)})});close();integrationSandboxModal(id)};
 document.querySelectorAll('[data-feed-extend]').forEach(b=>b.onclick=async()=>{await api(`/api/integrations/${id}/sandbox/events/${encodeURIComponent(b.dataset.feedExtend)}`,{method:'PATCH',body:JSON.stringify({departure_date:addIsoDays(b.dataset.dep,1),status:'active'})});close();integrationSandboxModal(id)});
 document.querySelectorAll('[data-feed-toggle]').forEach(b=>b.onclick=async()=>{await api(`/api/integrations/${id}/sandbox/events/${encodeURIComponent(b.dataset.feedToggle)}`,{method:'PATCH',body:JSON.stringify({status:b.dataset.status==='cancelled'?'active':'cancelled'})});close();integrationSandboxModal(id)});
 $('#loadIcal').onclick=async()=>{const text=$('#icalSample').value.trim();if(!text)return;await api(`/api/integrations/${id}/sandbox/ical`,{method:'POST',body:JSON.stringify({ical_text:text,replace_feed:$('#replaceIcal').checked})});close();integrationSandboxModal(id)};
}

function syncPreviewCard(c){return `<article class="sync-change ${c.kind}"><span class="change-kind">${syncKindLabel(c.kind)}</span><div class="change-main"><h4>${esc(c.guest_name)}</h4><p><b>${esc(c.property_name)}</b> · ${fmtDate(c.arrival_date)} → ${fmtDate(c.departure_date)} · ${c.guest_count} ${v23('guestCount').toLowerCase()}</p><small>${esc(c.external_ref)}</small></div><p class="change-reason">${syncReason(c.kind)}</p></article>`}
async function runSyncPreview(id){
 let d;
 try{d=await api(`/api/integrations/${id}/sync/preview`,{method:'POST'})}catch(err){document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="syncErrorModal"><div class="modal-card small-modal"><span class="eyebrow">${v23('feedOutage')}</span><h2>${v23('feedUnavailable')}</h2><p>${esc(err.message)}</p><div class="modal-actions"><button class="btn primary" id="syncErrorClose">${v23('close')}</button></div></div></div>`);$('#syncErrorClose').onclick=()=>$('#syncErrorModal')?.remove();return}
 const actionable=d.counts.new+d.counts.changed+d.counts.cancelled;
 document.body.insertAdjacentHTML('beforeend',`<div class="modal sync-preview-modal" id="syncPreviewModal"><div class="modal-card sync-preview-card"><div class="modal-title"><div><span class="eyebrow">${v23('dryRun')}</span><h2>${v23('syncPreview')}</h2><p>${v23('previewDesc')}</p></div><button type="button" class="modal-x" id="closeSyncPreview">×</button></div><div class="preview-counts"><span class="new"><b>${d.counts.new}</b>${v23('newBooking')}</span><span class="changed"><b>${d.counts.changed}</b>${v23('changedBooking')}</span><span class="cancelled"><b>${d.counts.cancelled}</b>${v23('cancelledBooking')}</span><span class="conflict"><b>${d.counts.conflict}</b>${v23('conflict')}</span><span><b>${d.counts.unchanged}</b>${v23('unchangedBooking')}</span></div><div class="sync-change-list">${d.changes.map(syncPreviewCard).join('')}</div><div class="sync-preview-note"><span>◎</span><p>${v23('actionsSafe')}</p></div><div class="modal-actions"><button class="btn" id="cancelSyncPreview">${v23('close')}</button><button class="btn primary" id="applySync" ${actionable?'':'disabled'}>${actionable?v23('applyImport'):v23('nothingToImport')}</button></div></div></div>`);
 const close=()=>$('#syncPreviewModal')?.remove();$('#closeSyncPreview').onclick=close;$('#cancelSyncPreview').onclick=close;
 $('#applySync').onclick=async()=>{const btn=$('#applySync');btn.disabled=true;btn.textContent='…';const out=await api(`/api/integrations/${id}/sync/apply`,{method:'POST'});btn.textContent=`✓ ${v23('importComplete')} · ${out.counts.applied} ${v23('applied')}${out.counts.skipped?` · ${out.counts.skipped} ${v23('skipped')}`:''}`;setTimeout(()=>{close();ownerIntegrations()},900)};
}

function actionDisplay(a){const label=a.payload?.label||a.action_type.replaceAll('_',' ');return `<article class="sim-action"><div class="sim-action-icon ${a.status}">${a.status==='simulated'?'◌':a.status==='executed'?'✓':'…'}</div><div><span>${esc(a.action_type.replaceAll('_',' '))}</span><b>${esc(label)}</b><small>${new Date(a.created_at).toLocaleString(uiLang)} · ${esc(a.operating_mode)}</small></div>${a.reversible&&a.status==='executed'?`<button class="text-btn undo-action" data-action="${a.id}">${v22('undo')}</button>`:''}</article>`}
async function ownerSimulation(){
 const [org,actions,memory,prefs]=await Promise.all([api('/api/organization'),api('/api/rosa/actions'),api('/api/memory'),api('/api/notifications/preferences')]);
 const counts={simulated:actions.filter(x=>x.status==='simulated').length,awaiting:actions.filter(x=>x.status==='awaiting_approval').length,executed:actions.filter(x=>x.status==='executed').length},mode=org.operating_mode||'observe';
 const desc={observe:'Real data may be analyzed, but Delvane records proposed actions instead of changing operational records.',assist:'Delvane prepares actions. A human approval is required before operational changes.',autonomous:'Only actions explicitly allowed by Train Delvane may execute automatically. High-risk authority rules remain blocked.'};
 const events={new_booking:'New booking',cancellation:'Cancellation',turnover_risk:'Same-day turnover risk',registration_due:'Registration due',cleaner_late:'Cleaner late',maintenance_risk:'Maintenance risk'};
 const content=`<section class="top compact"><span class="eyebrow">PRODUCTION PILOT CONTROL</span><h1>${v22('simulationTitle')}</h1><p>${v22('simulationDesc')}</p></section><section class="mode-control"><div class="mode-control-head"><div><span>${v22('currentMode')}</span><strong class="mode-${mode}">${v22(mode)}</strong></div><p>${esc(desc[mode])}</p></div><div class="mode-options">${['observe','assist','autonomous'].map(m=>`<button class="mode-option ${m===mode?'active':''}" data-mode="${m}"><span>${v22(m)}</span><p>${esc(desc[m])}</p><i>${m===mode?'✓':'→'}</i></button>`).join('')}</div></section><section class="intel-metrics v22-metrics"><article><span>${v22('simulated')}</span><strong>${counts.simulated}</strong></article><article><span>${v22('awaiting')}</span><strong>${counts.awaiting}</strong></article><article><span>${v22('executed')}</span><strong>${counts.executed}</strong></article></section><section class="v22-two-col"><div class="v22-panel"><div class="section-head"><div><span class="eyebrow">SIMULATION LEDGER</span><h2>${v22('wouldDo')}</h2></div></div><div class="sim-actions">${actions.length?actions.slice(0,30).map(actionDisplay).join(''):`<div class="empty">${v22('noActions')}</div>`}</div></div><div class="v22-panel"><div class="section-head"><div><span class="eyebrow">PREFERENCES</span><h2>${v22('notifications')}</h2></div></div><div class="notification-settings">${Object.entries(events).map(([k,label])=>`<label><input type="checkbox" data-notify="${k}" ${prefs[k]!==false?'checked':''}><span>${esc(label)}</span></label>`).join('')}<button class="btn" id="saveNotifications">${v22('save')}</button></div></div></section><section class="v22-panel memory-panel"><div class="section-head"><div><span class="eyebrow">STRUCTURED BUSINESS MEMORY</span><h2>${v22('memory')}</h2></div><small>Facts, not hidden model memory.</small></div><div class="memory-columns"><div>${memory.business.map(x=>`<article><b>${esc(x.memory_key.replaceAll('_',' '))}</b><span>${esc(x.value.note||x.value.topic||JSON.stringify(x.value))}</span><small>${esc(x.subject_type)} · confidence ${Math.round(x.confidence*100)}%</small></article>`).join('')||'<div class="empty">—</div>'}</div><div>${memory.guest_preferences.map(x=>`<article><b>${esc(x.full_name)}</b><span>${esc(x.preference_key.replaceAll('_',' '))}: ${esc(x.preference_value)}</span><small>${esc(x.source)}</small></article>`).join('')||'<div class="empty">—</div>'}</div></div></section>`;
 app.innerHTML=shell(content,'simulation');wireShell();document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=async()=>{const next=b.dataset.mode;if(next===org.operating_mode)return;if(next==='autonomous'&&!confirm('Enable AUTONOMOUS mode for this local demo? Only Delvane actions marked Automatic can execute.'))return;const r=await api('/api/organization/mode',{method:'PATCH',body:JSON.stringify({mode:next})});me.operating_mode=r.mode;ownerSimulation()});document.querySelectorAll('.undo-action').forEach(b=>b.onclick=async()=>{await api(`/api/rosa/actions/${b.dataset.action}/undo`,{method:'POST'});ownerSimulation()});$('#saveNotifications').onclick=async()=>{const preferences={};document.querySelectorAll('[data-notify]').forEach(x=>preferences[x.dataset.notify]=x.checked);await api('/api/notifications/preferences',{method:'PUT',body:JSON.stringify({preferences})});$('#saveNotifications').textContent='✓ '+v22('save');setTimeout(()=>{$('#saveNotifications')&&($('#saveNotifications').textContent=v22('save'))},900)};
}

async function ownerSecurity(){
 const [sec,audit,retention]=await Promise.all([api('/api/security'),api('/api/audit'),api('/api/retention')]);
 const content=`<section class="top compact"><span class="eyebrow">SECURITY / V2.2.3 FOUNDATION</span><h1>${v22('securityTitle')}</h1><p>${v22('securityDesc')}</p></section><section class="security-score"><div class="security-ring"><strong>V2.2.3</strong><span>foundation</span></div><div><h2>Production-shaped, still local.</h2><p>Tenant isolation, server-side roles, scrypt passwords, hashed session tokens, CSRF protection, security headers and audit evidence are active. MFA and production HTTPS are intentionally not claimed as complete in this local build.</p></div></section><section class="security-metrics"><article><span>${v22('activeSessions')}</span><strong>${sec.sessions.length}</strong></article><article><span>${v22('mfaUsers')}</span><strong>${sec.mfa_enabled_users}/${sec.active_users}</strong><small>production requirement</small></article><article><span>${v22('passwords')}</span><strong>${esc(sec.password_scheme)}</strong></article><article><span>${v22('csrf')}</span><strong>ACTIVE</strong></article><article><span>${v22('tenant')}</span><strong>SERVER</strong><small>organization scoped</small></article><article><span>Secure cookie</span><strong>${sec.secure_cookie_required?'ON':'LOCAL OFF'}</strong><small>${sec.secure_cookie_required?'HTTPS mode':'enabled automatically for production HTTPS'}</small></article></section><section class="v22-two-col"><div class="v22-panel"><div class="section-head"><div><span class="eyebrow">AUTHENTICATION</span><h2>${v22('sessions')}</h2></div></div><div class="session-list">${sec.sessions.map(x=>`<article><div><b>${esc(x.full_name)}</b><span>${esc(x.role)} · ${esc(x.ip_address||'local')}</span><small>${new Date(x.last_seen_at).toLocaleString(uiLang)} · ${esc((x.user_agent||'').slice(0,80))}</small></div><button class="text-btn revoke-session" data-session="${x.id}">${v22('revoke')}</button></article>`).join('')}</div></div><div class="v22-panel"><div class="section-head"><div><span class="eyebrow">LEAST PRIVILEGE</span><h2>Role permissions</h2></div></div><div class="permission-grid">${Object.entries(sec.permissions).map(([role,perms])=>`<article><b>${esc(roleLabel(role))}</b><span>${perms.length} permissions</span><small>${esc(perms.slice(0,5).join(' · '))}${perms.length>5?' …':''}</small></article>`).join('')}</div></div></section><section class="v22-two-col"><div class="v22-panel"><div class="section-head"><div><span class="eyebrow">EVIDENCE</span><h2>${v22('audit')}</h2></div></div><div class="audit-list">${audit.slice(0,35).map(x=>`<article><i></i><div><b>${esc(x.summary)}</b><span>${esc(x.event_type)} · ${esc(x.actor_name||x.actor_type)}</span><small>${new Date(x.created_at).toLocaleString(uiLang)}</small></div></article>`).join('')}</div></div><div class="v22-panel"><div class="section-head"><div><span class="eyebrow">PRIVACY</span><h2>${v22('retention')}</h2></div></div><div class="retention-list">${retention.map(x=>`<article><b>${esc(x.data_class.replaceAll('_',' '))}</b><span>${x.retention_days?`${x.retention_days} ${v22('days')}`:v22('notConfigured')}</span><small>${esc(x.description)}</small></article>`).join('')}</div></div></section>`;
 app.innerHTML=shell(content,'security');wireShell();document.querySelectorAll('.revoke-session').forEach(b=>b.onclick=async()=>{if(!confirm('Revoke this active session?'))return;await api(`/api/security/sessions/${b.dataset.session}`,{method:'DELETE'});try{await ownerSecurity()}catch(_){}});
}

function openGlobalSearch(){
 if($('#globalSearchModal'))return;
 document.body.insertAdjacentHTML('beforeend',`<div class="modal global-search-modal" id="globalSearchModal"><div class="modal-card search-modal-card"><div class="modal-title"><div><span class="eyebrow">${v22('globalSearch').toUpperCase()}</span><h2>${v22('search')}</h2></div><button class="modal-x" id="closeGlobalSearch">×</button></div><div class="global-search-input"><span>⌕</span><input id="globalSearchInput" placeholder="${v22('searchPlaceholder')}" autocomplete="off"></div><div id="globalSearchResults" class="global-search-results"><div class="empty">${v22('searchPlaceholder')}</div></div></div></div>`);
 const close=()=>$('#globalSearchModal')?.remove();$('#closeGlobalSearch').onclick=close;$('#globalSearchModal').onclick=e=>{if(e.target.id==='globalSearchModal')close()};const input=$('#globalSearchInput');input.focus();let timer;input.oninput=()=>{clearTimeout(timer);timer=setTimeout(async()=>{const q=input.value.trim();if(q.length<2){$('#globalSearchResults').innerHTML=`<div class="empty">${v22('searchPlaceholder')}</div>`;return}const d=await api('/api/search?q='+encodeURIComponent(q));$('#globalSearchResults').innerHTML=d.results.length?d.results.map(x=>`<button data-search-type="${x.type}" data-search-id="${x.id}"><span>${esc(x.type)}</span><b>${esc(x.title)}</b><small>${esc(x.detail||'')}</small><i>→</i></button>`).join(''):`<div class="empty">${v22('noResults')}</div>`;wireSearchResults(close)},180)};
}
function wireSearchResults(close){document.querySelectorAll('[data-search-id]').forEach(b=>b.onclick=()=>{const type=b.dataset.searchType,id=b.dataset.searchId;close();if(type==='property')propertyOverviewModal(id);else if(type==='guest')guestProfileModal(id);else if(type==='reservation')openReservationById(id);else if(type==='message')ownerInbox(id)})}

async function navigate(v){
 currentNav=v;
 if(['owner','manager'].includes(me.role)){
   if(v==='intelligence')return ownerIntelligence();if(v==='operations')return ownerOperations();if(v==='maintenance')return ownerMaintenance();if(v==='supplies')return ownerSupplies();if(v==='reservations')return ownerReservations();if(v==='guests')return ownerGuests();if(v==='registration')return ownerRegistration();if(v==='integrations')return ownerIntegrations();if(v==='simulation')return ownerSimulation();if(v==='security')return ownerSecurity();if(v==='inbox')return ownerInbox();if(v==='train')return ownerTrainDelvane();if(v==='team')return ownerTeam();return ownerToday();
 }
 if(v==='maintenance'||me.role==='maintenance')return workerMaintenance();return workerToday(v==='schedule');
}


