function v25(k){return (V25_I18N[uiLang]||V25_I18N.en)[k]||V25_I18N.en[k]||k}


function maintenanceStateLabel(status){
  if(status==='reported'||status==='open')return v25('reported');
  if(status==='assigned')return v25('assigned');
  if(status==='in_progress')return statusLabel('in_progress');
  if(status==='resolved')return v25('markResolved').replace(/^./,c=>c.toUpperCase()).replace(/.*/,v25('markResolved')) && (uiLang==='en'?'Resolved':localizeOperationalText('Resolved'));
  if(status==='verified')return v25('verified');
  return status;
}
function compactStatus(status){
  const m={reported:v25('reported'),open:v25('reported'),assigned:v25('assigned'),in_progress:statusLabel('in_progress'),resolved:uiLang==='hu'?'Megoldva':uiLang==='de'?'Gelöst':uiLang==='es'?'Resuelto':uiLang==='fr'?'Résolu':uiLang==='it'?'Risolto':uiLang==='pt'?'Resolvido':uiLang==='pl'?'Rozwiązane':uiLang==='nl'?'Opgelost':uiLang==='ro'?'Rezolvat':uiLang==='cs'?'Vyřešeno':uiLang==='sk'?'Vyriešené':uiLang==='hr'?'Riješeno':uiLang==='sr'?'Rešeno':uiLang==='uk'?'Вирішено':uiLang==='ru'?'Решено':uiLang==='tr'?'Çözüldü':uiLang==='zh'?'已解决':'Resolved',verified:v25('verified')};return m[status]||status;
}

async function ownerToday(){
  const [cmd,d]=await Promise.all([api('/api/operations/today-command'),api('/api/owner/dashboard')]);
  const turnovers=cmd.cleaning.filter(x=>x.deadline_time).length;
  const issueCount=cmd.maintenance.length;
  const content=`<section class="top compact v25-command-top"><div><span class="eyebrow">${esc(cmd.date)}</span><h1>${v25('todayCommand')}</h1><p>${cmd.urgent_count?`<b>${cmd.urgent_count}</b> ${v25('urgent').toLowerCase()}`:v25('readyToFinish')}</p></div>${cmd.urgent_count?`<span class="v25-urgent-pill">${cmd.urgent_count} ${v25('urgent')}</span>`:'<span class="v25-clear-pill">✓</span>'}</section>
  <section class="v25-metric-row"><article><span>${localizeOperationalText('Arrivals')}</span><strong>${cmd.arrivals.length}</strong></article><article><span>${localizeOperationalText('Departures')}</span><strong>${cmd.departures.length}</strong></article><article><span>${v25('turnovers')}</span><strong>${turnovers}</strong></article><article><span>${v25('registrationIssues')}</span><strong>${cmd.registration_risks.length}</strong></article></section>
  <section class="v25-today-board"><div class="v25-today-column"><header><span class="eyebrow">${localizeOperationalText('Arrivals')}</span><b>${cmd.arrivals.length}</b></header>${cmd.arrivals.length?cmd.arrivals.map(r=>`<button class="v25-action-row" data-open-res="${r.id}"><span class="v25-time">${esc(r.arrival_time||r.checkin_time||'15:00')}</span><span><b>${esc(r.guest_name)}</b><small>${esc(r.property_name)} · ${r.guest_count} ${localizeOperationalText('guests')}</small></span><i>${r.registration_status==='complete'?'✓':'!'}</i></button>`).join(''):`<div class="empty">—</div>`}</div>
  <div class="v25-today-column"><header><span class="eyebrow">${v25('turnovers')}</span><b>${cmd.cleaning.length}</b></header>${cmd.cleaning.length?cmd.cleaning.map(t=>`<button class="v25-action-row" data-property="${esc(d.properties.find(p=>p.name===t.property_name)?.id||'')}"><span class="v25-time">${esc(t.deadline_time||'—')}</span><span><b>${esc(t.property_name)}</b><small>${esc(t.assigned_name||localizeOperationalText('Unassigned'))} · ${statusLabel(t.status)}</small></span><i>↻</i></button>`).join(''):`<div class="empty">—</div>`}</div>
  <div class="v25-today-column"><header><span class="eyebrow">${v25('openMaintenance')}</span><b>${issueCount}</b></header>${cmd.maintenance.length?cmd.maintenance.slice(0,5).map(m=>`<button class="v25-action-row" data-maintenance-open="1"><span class="severity ${esc(m.severity)}">${esc(m.severity)}</span><span><b>${esc(m.title)}</b><small>${esc(m.property_name)} · ${compactStatus(m.status)}</small></span><i>›</i></button>`).join(''):`<div class="empty">—</div>`}</div></section>
  <section><div class="section-head"><div><span class="eyebrow">${localizeOperationalText('Properties')}</span><h2>${localizeOperationalText('Properties')}</h2></div></div><div class="property-grid">${d.properties.map(p=>`<button type="button" class="property property-click" data-property="${p.id}"><div class="property-top"><h3>${esc(p.name)}</h3><span class="state ${p.state}">${localizeOperationalText(p.state==='ready'?'Ready':p.state==='cleaning'?'Cleaning':'Attention')}</span></div><p>${p.reasons.length?esc(localizeOperationalText(p.reasons.join(' · '))):localizeOperationalText('No blockers detected.')}</p><div class="property-meta"><span>${localizeOperationalText('Next:')} ${p.next_arrival?fmtDate(p.next_arrival):'—'}</span><span class="property-open">${localizeOperationalText('Open →')}</span></div></button>`).join('')}</div></section>`;
  app.innerHTML=shell(content,'today');wireShell();
  document.querySelectorAll('[data-open-res]').forEach(b=>b.onclick=()=>openReservationById(b.dataset.openRes));
  document.querySelectorAll('[data-property]').forEach(b=>b.onclick=()=>b.dataset.property&&propertyOverviewModal(b.dataset.property));
  document.querySelectorAll('[data-maintenance-open]').forEach(b=>b.onclick=()=>ownerMaintenance());
}

async function reservationModal(r,props,initialDate=null){
  if(!r)return legacyReservationModal(r,props,initialDate);
  const d=await api(`/api/reservations/${r.id}/detail`); const x=d.reservation;
  const requests=requestList(x); const reg=d.registration||[]; const cleaning=d.cleaning||[];
  document.body.insertAdjacentHTML('beforeend',`<div class="modal v25-modal" id="reservationModal"><div class="modal-card v25-reservation-workspace"><header class="v25-res-header"><div><span class="source">${esc(x.source)}${x.external_ref?' · '+esc(x.external_ref):''}</span><h2>${esc(x.guest_name)}</h2><p>${esc(x.property_name)} · ${fmtDate(x.arrival_date)} → ${fmtDate(x.departure_date)}</p></div><div class="v25-res-head-actions"><button class="btn" id="v25EditBooking">${v25('editBooking')}</button><button class="modal-x" id="closeReservation">×</button></div></header>
    <section class="v25-res-stats"><article><span>${v25('payment')}</span><b>${esc(localizeOperationalText(x.payment_status||'unknown'))}</b><small>${x.total_huf?new Intl.NumberFormat(rosaLocaleCode()).format(x.total_huf)+' Ft':'—'}</small></article><article><span>${localizeOperationalText('Registration')}</span><b>${esc(localizeOperationalText(x.registration_status||'incomplete'))}</b><small>${reg.length}/${x.guest_count}</small></article><article><span>${v25('arrivalTime')}</span><b>${esc(x.arrival_time||x.checkin_time)}</b><small>${esc(x.property_name)}</small></article><article><span>${localizeOperationalText('Guest')}</span><b>${x.guest_count}</b><small>${esc(d.guest?.preferred_language||'—')}</small></article></section>
    <nav class="v25-res-tabs"><button class="active" data-r-tab="overview">${v25('stayOverview')}</button><button data-r-tab="prep">${v25('preparation')}</button><button data-r-tab="comms">${v25('communication')}</button><button data-r-tab="activity">${v25('activity')}</button></nav>
    <div class="v25-res-body" id="v25ResBody"></div>
  </div></div>`);
  const body=$('#v25ResBody');
  const panes={
    overview:()=>`<div class="v25-res-two"><section class="v25-detail-panel"><span class="eyebrow">${v25('stayOverview')}</span><div class="v25-kv"><span>${localizeOperationalText('Property')}</span><b>${esc(x.property_name)}</b><small>${esc(x.address||'')}</small></div><div class="v25-kv"><span>${localizeOperationalText('Check-in')}</span><b>${esc(x.checkin_time)}</b></div><div class="v25-kv"><span>${localizeOperationalText('Checkout')}</span><b>${esc(x.checkout_time)}</b></div><div class="v25-kv"><span>${v223('specialRequests')}</span><b>${requests.length?requests.map(esc).join(' · '):'—'}</b></div></section><section class="v25-detail-panel"><span class="eyebrow">${v25('preparation')}</span><label>${v25('arrivalTime')}<input id="v25ArrivalTime" type="time" value="${esc(x.arrival_time||'')}"></label><label>${v25('payment')}<select id="v25Payment">${['unknown','unpaid','partial','paid','refunded'].map(v=>`<option value="${v}" ${x.payment_status===v?'selected':''}>${localizeOperationalText(v)}</option>`).join('')}</select></label><label>${localizeOperationalText('Registration')}<select id="v25Registration">${['incomplete','pending','complete'].map(v=>`<option value="${v}" ${x.registration_status===v?'selected':''}>${localizeOperationalText(v)}</option>`).join('')}</select></label><button class="btn primary" id="v25SaveOps">${localizeOperationalText('Save')}</button></section></div>`,
    prep:()=>`<div class="v25-res-two"><section class="v25-detail-panel"><span class="eyebrow">${localizeOperationalText('Registration')}</span>${reg.length?reg.map(g=>`<div class="v25-person-row"><span class="account-avatar">${esc(g.full_name.split(/\s+/).map(v=>v[0]).slice(0,2).join(''))}</span><span><b>${esc(g.full_name)}</b><small>${esc(g.nationality||'—')}</small></span><i class="${g.completeness==='complete'?'ok':'warn'}">${g.completeness==='complete'?'✓':'!'}</i></div>`).join(''):`<div class="empty">—</div>`}</section><section class="v25-detail-panel"><span class="eyebrow">${v25('checklist')}</span>${cleaning.length?cleaning.map(t=>`<div class="v25-clean-link"><div><b>${esc(t.title)}</b><small>${fmtDate(t.scheduled_date)} · ${esc(t.assigned_name||localizeOperationalText('Unassigned'))}</small></div><span class="state ${t.status==='complete'?'ready':t.status==='in_progress'?'cleaning':'attention'}">${statusLabel(t.status)}</span></div>`).join(''):`<div class="empty">—</div>`}${d.maintenance?.length?`<div class="v25-maint-warning"><b>${v25('openMaintenance')}</b><span>${d.maintenance.map(m=>esc(m.title)).join(' · ')}</span></div>`:''}</section></div>`,
    comms:()=>`<div class="v25-res-two"><section class="v25-detail-panel"><span class="eyebrow">${localizeOperationalText('Messages')}</span>${d.messages.length?d.messages.map(m=>`<article class="v25-message-item"><small>${esc(m.source)} · ${new Date(m.received_at).toLocaleString(rosaLocaleCode())}</small><b>${esc(m.sender_name||m.subject||'')}</b><p>${esc(m.body)}</p></article>`).join(''):`<div class="empty">${v25('noMessages')}</div>`}</section><section class="v25-detail-panel"><span class="eyebrow">${v25('addNote')}</span><textarea id="v25Note" placeholder="${v25('notePlaceholder')}"></textarea><button class="btn primary" id="v25AddNote">${v25('addNote')}</button><div class="v25-note-list">${d.notes.length?d.notes.map(n=>`<article><b>${esc(n.author_name||'Delvane')}</b><small>${new Date(n.created_at).toLocaleString(rosaLocaleCode())}</small><p>${esc(n.body)}</p></article>`).join(''):`<div class="empty">${v25('noNotes')}</div>`}</div></section></div>`,
    activity:()=>`<section class="v25-detail-panel"><span class="eyebrow">${v25('activity')}</span><div class="life-timeline">${d.events.length?d.events.map(e=>`<article><i></i><div><time>${new Date(e.created_at).toLocaleString(rosaLocaleCode())}</time><b>${esc(localizeOperationalText(e.summary))}</b><span>${esc(e.event_type)}</span></div></article>`).join(''):`<div class="empty">${v25('noActivity')}</div>`}</div></section>`
  };
  const wirePane=(name)=>{body.innerHTML=panes[name](); if(name==='overview')$('#v25SaveOps').onclick=async()=>{await api(`/api/reservations/${r.id}/operations`,{method:'PATCH',body:JSON.stringify({arrival_time:$('#v25ArrivalTime').value||'',payment_status:$('#v25Payment').value,registration_status:$('#v25Registration').value})});$('#reservationModal').remove();openReservationById(r.id)}; if(name==='comms')$('#v25AddNote').onclick=async()=>{const text=$('#v25Note').value.trim();if(!text)return;await api(`/api/reservations/${r.id}/notes`,{method:'POST',body:JSON.stringify({body:text})});$('#reservationModal').remove();openReservationById(r.id)};};
  wirePane('overview');
  document.querySelectorAll('[data-r-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-r-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');wirePane(b.dataset.rTab)});
  const close=()=>$('#reservationModal')?.remove();$('#closeReservation').onclick=close;$('#reservationModal').onclick=e=>{if(e.target.id==='reservationModal')close()};
  $('#v25EditBooking').onclick=()=>{close();legacyReservationModal(r,props)};
}

function v25TaskCard(t){
  const done=Number(t.checklist_done||0),total=Number(t.checklist_total||0),pct=total?Math.round(done/total*100):0,reqs=t.special_requests||[];
  return `<article class="v25-cleaning-card ${t.status}"><header><div><span class="eyebrow">${fmtDate(t.scheduled_date)}</span><h2>${esc(t.property_name)}</h2></div><span class="state ${t.status==='complete'?'ready':t.status==='in_progress'?'cleaning':'attention'}">${statusLabel(t.status)}</span></header><div class="v25-cleaning-meta"><span><b>${esc(t.earliest_time||'—')}</b><small>${localizeOperationalText('Checkout')}</small></span><span><b>${esc(t.deadline_time||'—')}</b><small>${localizeOperationalText('Check-in')}</small></span><span><b>${t.next_guest_count||'—'}</b><small>${localizeOperationalText('guests')}</small></span></div>${reqs.length?`<div class="guest-needs">${reqs.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}<div class="v25-check-head"><div><b>${v25('checklist')}</b><small>${done}/${total} · ${Math.max(0,total-done)} ${v25('remaining')}</small></div><strong>${pct}%</strong></div><div class="v25-check-progress"><i style="width:${pct}%"></i></div><div class="v25-checklist">${(t.checklist||[]).map(i=>`<label class="${i.completed?'done':''}"><input type="checkbox" data-task="${t.id}" data-check="${i.id}" ${i.completed?'checked':''} ${t.status==='complete'?'disabled':''}><span>${esc(localizeOperationalText(i.label))}</span></label>`).join('')}</div><footer>${t.status==='open'?`<button class="btn primary start-task" data-id="${t.id}">${v25('startCleaning')}</button>`:t.status==='in_progress'?`<button class="btn primary finish-task" data-id="${t.id}" ${done<total?'disabled':''}>${done===total?v25('readyToFinish'):v25('finishCleaning')}</button>`:`<span class="v25-finished">✓ ${statusLabel('complete')}</span>`}</footer></article>`;
}

async function workerToday(schedule=false){
  const d=await api('/api/worker/dashboard');
  const tasks=(schedule?d.tasks:d.tasks.filter(t=>t.scheduled_date===d.date||t.status==='in_progress'));
  const content=`<section class="top compact"><span class="eyebrow">${schedule?tr('schedule'):tr('myday')}</span><h1>${schedule?tr('schedule'):v25('todayCommand')}</h1><p>${tasks.length} ${localizeOperationalText('active items')}</p></section><section class="v25-worker-grid">${tasks.length?tasks.map(v25TaskCard).join(''):`<div class="empty">${localizeOperationalText('Nothing currently scheduled.')}</div>`}</section>`;
  app.innerHTML=shell(content,schedule?'schedule':'today');wireShell();
  document.querySelectorAll('[data-check]').forEach(c=>c.onchange=async()=>{await api(`/api/work-tasks/${c.dataset.task}/checklist/${c.dataset.check}`,{method:'PATCH',body:JSON.stringify({completed:c.checked})});workerToday(schedule)});
  document.querySelectorAll('.start-task').forEach(b=>b.onclick=async()=>{await api(`/api/work-tasks/${b.dataset.id}/start`,{method:'POST'});workerToday(schedule)});
  document.querySelectorAll('.finish-task').forEach(b=>b.onclick=()=>openFinish(b.dataset.id));
}

function maintenanceRail(status){const stages=['reported','assigned','in_progress','resolved','verified'];let idx=Math.max(0,stages.indexOf(status==='open'?'reported':status));return `<div class="v25-maint-rail">${stages.map((s,i)=>`<i class="${i<idx?'done':i===idx?'current':''}"><span>${i<idx?'✓':i+1}</span><small>${compactStatus(s)}</small></i>`).join('')}</div>`}
async function ownerMaintenance(){
 const [cases,props]=await Promise.all([api('/api/maintenance'),api('/api/properties')]);
 const content=`<section class="top compact"><span class="eyebrow">${tr('maintenance').toUpperCase()}</span><h1>${v25('maintenanceWorkflow')}</h1><p>${cases.filter(x=>!['resolved','verified'].includes(x.status)).length} ${localizeOperationalText('active items')}</p></section><div class="section-head"><div></div><button class="btn primary" id="newMaintenance">+ ${localizeOperationalText('Maintenance')}</button></div><section class="v25-maint-grid">${cases.map(c=>`<article class="v25-maint-card"><header><div><span class="severity ${c.severity}">${esc(c.severity)}</span><span>${esc(c.property_name)}</span></div><span class="state ${c.status==='verified'?'ready':c.status==='in_progress'?'cleaning':'attention'}">${compactStatus(c.status)}</span></header><h3>${esc(c.title)}</h3><p>${esc(c.detail)}</p>${maintenanceRail(c.status)}<footer><span>${esc(c.assigned_name||localizeOperationalText('Unassigned'))}</span><div>${(c.status==='reported'||c.status==='assigned'||c.status==='open')?`<button class="btn start-maint" data-id="${c.id}">${v25('startWork')}</button>`:c.status==='in_progress'?`<button class="btn primary resolve-maint" data-id="${c.id}">${v25('markResolved')}</button>`:c.status==='resolved'?`<button class="btn primary verify-maint" data-id="${c.id}">${v25('verify')}</button>`:''}</div></footer></article>`).join('')}</section>`;
 app.innerHTML=shell(content,'maintenance');wireShell();$('#newMaintenance').onclick=()=>maintenanceModal(props,ownerMaintenance);
 const set=async(id,status)=>{await api(`/api/maintenance/${id}/status`,{method:'PATCH',body:JSON.stringify({status})});ownerMaintenance()};document.querySelectorAll('.start-maint').forEach(b=>b.onclick=()=>set(b.dataset.id,'in_progress'));document.querySelectorAll('.resolve-maint').forEach(b=>b.onclick=()=>set(b.dataset.id,'resolved'));document.querySelectorAll('.verify-maint').forEach(b=>b.onclick=()=>set(b.dataset.id,'verified'));
}

async function workerMaintenance(){
 const [cases,props]=await Promise.all([api('/api/maintenance'),api('/api/properties')]);const maint=me.role==='maintenance';
 const content=`<section class="top compact"><span class="eyebrow">${tr('maintenance').toUpperCase()}</span><h1>${v25('maintenanceWorkflow')}</h1><p>${cases.length} ${localizeOperationalText('active items')}</p></section>${!maint?`<button class="btn primary" id="newMaintenance">+ ${localizeOperationalText('Maintenance')}</button>`:''}<section class="v25-maint-grid">${cases.map(c=>`<article class="v25-maint-card"><header><span class="severity ${c.severity}">${esc(c.severity)}</span><span class="state ${c.status==='resolved'?'ready':c.status==='in_progress'?'cleaning':'attention'}">${compactStatus(c.status)}</span></header><h3>${esc(c.title)}</h3><p>${esc(c.property_name)} · ${esc(c.detail)}</p>${maintenanceRail(c.status)}${maint?`<footer>${(c.status==='reported'||c.status==='assigned'||c.status==='open')?`<button class="btn start-maint" data-id="${c.id}">${v25('startWork')}</button>`:c.status==='in_progress'?`<button class="btn primary resolve-maint" data-id="${c.id}">${v25('markResolved')}</button>`:''}</footer>`:''}</article>`).join('')}</section>`;
 app.innerHTML=shell(content,'maintenance');wireShell();$('#newMaintenance')?.addEventListener('click',()=>maintenanceModal(props,workerMaintenance));const set=async(id,status)=>{await api(`/api/maintenance/${id}/status`,{method:'PATCH',body:JSON.stringify({status})});workerMaintenance()};document.querySelectorAll('.start-maint').forEach(b=>b.onclick=()=>set(b.dataset.id,'in_progress'));document.querySelectorAll('.resolve-maint').forEach(b=>b.onclick=()=>set(b.dataset.id,'resolved'));
}

