async function ownerSecurity(){
 const [sec,audit,retention,runtime]=await Promise.all([api('/api/security'),api('/api/audit'),api('/api/retention'),api('/api/system/runtime')]);
 const content=`<section class="top compact"><span class="eyebrow">${v25('productionCore').toUpperCase()}</span><h1>${v22('securityTitle')}</h1><p>${v22('securityDesc')}</p></section><section class="security-score v25-runtime"><div class="security-ring"><strong>V2.6</strong><span>${esc(runtime.database_backend)}</span></div><div><h2>${v25('productionCore')}</h2><p>${v25sys('deploymentRule')}</p><div class="v25-runtime-grid"><span><small>${v25sys('environment')}</small><b>${esc(runtime.environment)}</b></span><span><small>${v25sys('database')}</small><b>${esc(runtime.database_backend)}</b></span><span><small>${v25sys('schema')}</small><b>${esc(String(runtime.schema_version))}</b></span><span><small>${v25sys('version')}</small><b>${esc(runtime.version)}</b></span></div></div></section><section class="security-metrics"><article><span>${v22('activeSessions')}</span><strong>${sec.sessions.length}</strong></article><article><span>${v22('mfaUsers')}</span><strong>${sec.mfa_enabled_users}/${sec.active_users}</strong></article><article><span>${v22('passwords')}</span><strong>${esc(sec.password_scheme)}</strong></article><article><span>${v22('csrf')}</span><strong>ACTIVE</strong></article><article><span>${v22('tenant')}</span><strong>SERVER</strong></article><article><span>${localizeOperationalText('Secure cookie')}</span><strong>${sec.secure_cookie_required?'ON':'LOCAL OFF'}</strong></article></section><section class="v22-two-col"><div class="v22-panel"><div class="section-head"><div><span class="eyebrow">${localizeOperationalText('AUTHENTICATION')}</span><h2>${v22('sessions')}</h2></div></div><div class="session-list">${sec.sessions.map(x=>`<article><div><b>${esc(x.full_name)}</b><span>${esc(roleLabel(x.role))} · ${esc(x.ip_address||'local')}</span><small>${new Date(x.last_seen_at).toLocaleString(rosaLocaleCode())}</small></div><button class="text-btn revoke-session" data-session="${x.id}">${v22('revoke')}</button></article>`).join('')}</div></div><div class="v22-panel"><div class="section-head"><div><span class="eyebrow">${localizeOperationalText('LEAST PRIVILEGE')}</span><h2>${localizeOperationalText('Role permissions')}</h2></div></div><div class="permission-grid">${Object.entries(sec.permissions).map(([role,perms])=>`<article><b>${esc(roleLabel(role))}</b><span>${perms.length}</span><small>${esc(perms.slice(0,5).join(' · '))}${perms.length>5?' …':''}</small></article>`).join('')}</div></div></section><section class="v22-two-col"><div class="v22-panel"><div class="section-head"><div><span class="eyebrow">${localizeOperationalText('EVIDENCE')}</span><h2>${v22('audit')}</h2></div></div><div class="audit-list">${audit.slice(0,35).map(x=>`<article><i></i><div><b>${esc(localizeOperationalText(x.summary))}</b><span>${esc(x.event_type)} · ${esc(x.actor_name||x.actor_type)}</span><small>${new Date(x.created_at).toLocaleString(rosaLocaleCode())}</small></div></article>`).join('')}</div></div><div class="v22-panel"><div class="section-head"><div><span class="eyebrow">${localizeOperationalText('PRIVACY')}</span><h2>${v22('retention')}</h2></div></div><div class="retention-list">${retention.map(x=>`<article><b>${esc(x.data_class.replaceAll('_',' '))}</b><span>${x.retention_days?`${x.retention_days} ${v22('days')}`:v22('notConfigured')}</span><small>${esc(x.description)}</small></article>`).join('')}</div></div></section>`;
 app.innerHTML=shell(content,'security');wireShell();document.querySelectorAll('.revoke-session').forEach(b=>b.onclick=async()=>{if(!confirm('Revoke this active session?'))return;await api(`/api/security/sessions/${b.dataset.session}`,{method:'DELETE'});try{await ownerSecurity()}catch(_){}});
}



