function v26ProposalCard(p){
 const actionable=p.status==='awaiting_approval';
 return `<article class="v26-proposal ${p.status}"><div class="v26-proposal-icon">↗</div><div class="v26-proposal-main"><span>${v26('proposedAction')}</span><h4>${esc(p.title)}</h4><p>${esc(p.detail)}</p><div class="v26-proposal-meta"><b>${v26ProposalStatus(p)}</b><span>${v26('authority')}: ${esc(p.authority_mode)}</span><span>${v26('mode')}: ${esc(p.operating_mode)}</span></div></div>${actionable?`<div class="v26-proposal-actions"><button class="btn proposal-decline" data-proposal="${p.id}">${v26('decline')}</button><button class="btn primary proposal-approve" data-proposal="${p.id}">${v26('approve')}</button></div>`:''}</article>`;
}
