function rosaChatRichText(text){
 let out=esc(localizeOperationalText(text||''));
 out=out.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
 out=out.replace(/`([^`]+)`/g,'<code>$1</code>');
 return out.replace(/\n/g,'<br>');
}
function v26ChatHtml(detail){
 const msgs=detail?.messages||[]; if(!msgs.length)return `<div class="rosa-chat-empty"><img class="delvane-chat-logo" src="/static/delvane-icon.png" alt="Delvane logo"><h3>${v26('noConversation')}</h3><p>${v26('contextNotice')}</p></div>`;
 return msgs.map(m=>`<div class="rosa-chat-message ${m.role==='rosa'?'rosa':'user'}"><span class="chat-avatar">${m.role==='rosa'?'R':esc((me.full_name||'Y')[0].toUpperCase())}</span><div><small>${m.role==='rosa'?'ROSA AI':esc(me.full_name)}</small><p>${m.role==='rosa'?rosaChatRichText(m.content):esc(m.content)}</p>${m.role==='rosa'&&m.provider?`<em class="v26-message-provider route-${esc(m?.metadata?.route||'fallback')}">${esc(v262RouteLabel(m))}</em>`:''}</div></div>`).join('');
}
async function v26LoadConversation(){
 const detail=await api('/api/rosa/conversation');
 window.__rosaConversationId=detail.conversation.id;
 window.__rosaConversationDetail=detail;
 return detail;
}
function v26WireProposalButtons(){
 document.querySelectorAll('.proposal-approve').forEach(b=>b.onclick=()=>v26ResolveProposal(b.dataset.proposal,'approve'));
 document.querySelectorAll('.proposal-decline').forEach(b=>b.onclick=()=>v26ResolveProposal(b.dataset.proposal,'decline'));
}
async function v26ResolveProposal(id,decision){await api(`/api/rosa/proposals/${id}/resolve`,{method:'POST',body:JSON.stringify({decision})});await v26LoadConversation();await ownerIntelligence();}
async function sendDelvaneChat(){
 const input=$('#commandInput'),btn=$('#commandSend');if(!input||!btn)return;const display=input.value.trim();if(!display)return;
 const canonical=(input.dataset.canonicalDisplay===display&&input.dataset.canonical)?input.dataset.canonical:display;input.value='';delete input.dataset.canonical;delete input.dataset.canonicalDisplay;btn.disabled=true;
 const thread=$('#rosaChatThread');thread.insertAdjacentHTML('beforeend',`<div class="rosa-chat-message user"><span class="chat-avatar">${esc((me.full_name||'Y')[0].toUpperCase())}</span><div><small>${esc(me.full_name)}</small><p>${esc(display)}</p></div></div><div class="rosa-chat-message rosa thinking-message"><span class="chat-avatar">R</span><div><small>ROSA AI</small><p class="typing"><i></i><i></i><i></i><span>${v26('thinking')}</span></p></div></div>`);thread.scrollTop=thread.scrollHeight;
 try{const out=await api('/api/rosa/chat',{method:'POST',body:JSON.stringify({message:canonical,conversation_id:window.__rosaConversationId,language:uiLang})});window.__rosaConversationId=out.conversation_id;await v26LoadConversation();}catch(err){thread.insertAdjacentHTML('beforeend',`<div class="rosa-chat-message rosa"><span class="chat-avatar">R</span><div><small>ROSA AI</small><p>${esc(err.message)}</p></div></div>`)}
 btn.disabled=false;await ownerIntelligence();
}

