function v28(k){return V28_I18N[uiLang]?.[k]||V28_I18N.en[k]||k}

ownerPrimaryNav=function(){return [['today',tr('today')],['intelligence',tr('intelligence')],['reservations',tr('reservations')],['inbox',v28('reception')],['operations',tr('operations')]]};

const v28WireShellBase=wireShell;
wireShell=function(){
 v28WireShellBase();
 const util=$('.v22-utility');
 if(util&&!$('#v28Notifications')){
   const btn=document.createElement('button');btn.id='v28Notifications';btn.className='v28-notify-button';btn.innerHTML=`<span>◌</span><b id="v28NotifyCount">0</b>`;btn.title=v28('notifications');
   util.insertBefore(btn,$('#modeQuickBtn')||null);btn.onclick=openV28Notifications;
   api('/api/notifications').then(d=>{const n=$('#v28NotifyCount');if(n){n.textContent=d.unread;n.classList.toggle('empty',!d.unread)}}).catch(()=>{});
 }
};

async function openV28Notifications(){
 if($('#v28NotifyLayer'))return;
 const d=await api('/api/notifications');
 document.body.insertAdjacentHTML('beforeend',`<div class="v28-notify-layer" id="v28NotifyLayer"><button class="v28-notify-backdrop" id="v28NotifyBackdrop"></button><aside class="v28-notify-drawer"><header><div><span class="eyebrow">DELVANE</span><h2>${v28('notifications')}</h2></div><button id="v28NotifyClose">×</button></header><div class="v28-notify-actions"><button id="v28ReadAll">${v28('markAllRead')}</button></div><div class="v28-notify-list">${d.items.length?d.items.map(x=>`<button class="v28-note ${x.status==='unread'?'unread':''}" data-note="${x.id}"><span></span><div><b>${esc(x.title)}</b><p>${esc(x.detail||'')}</p><small>${new Date(x.created_at).toLocaleString(rosaLocaleCode())}</small></div></button>`).join(''):`<div class="v28-empty">${v28('noNotifications')}</div>`}</div></aside></div>`);
 const close=()=>$('#v28NotifyLayer')?.remove();$('#v28NotifyBackdrop').onclick=close;$('#v28NotifyClose').onclick=close;
 $('#v28ReadAll').onclick=async()=>{await api('/api/notifications/read-all',{method:'POST'});close();const n=$('#v28NotifyCount');if(n){n.textContent='0';n.classList.add('empty')}};
 document.querySelectorAll('[data-note]').forEach(b=>b.onclick=async()=>{await api(`/api/notifications/${b.dataset.note}/read`,{method:'POST'});b.classList.remove('unread')});
}

function v28ReceptionTabs(summary,active){
 return `<nav class="v28-reception-tabs"><button data-reception-tab="inbox" class="${active==='inbox'?'active':''}">${v28('inbox')} <b>${summary.new}</b></button><button data-reception-tab="scheduled" class="${active==='scheduled'?'active':''}">${v28('scheduled')} <b>${summary.scheduled}</b></button><button data-reception-tab="automations" class="${active==='automations'?'active':''}">${v28('automations')} <b>${summary.enabled_rules}</b></button></nav>`;
}
function v28ReceptionStatus(status){return ({new:'NEW',analyzed:'UNDERSTOOD',actioned:'ACTIONED',replied:'REPLIED',preview:v28('preview').toUpperCase(),awaiting_approval:v28('needsApproval').toUpperCase(),ready:v28('ready').toUpperCase(),simulated_sent:v28('simulated').toUpperCase(),cancelled:v28('cancelled').toUpperCase(),draft:'DRAFT'})[status]||String(status||'').toUpperCase()}
function v28AnalysisChips(a){
 const ex=a?.extracted||{};const chips=[];
 if(ex.property_name)chips.push(ex.property_name);if(ex.arrival_time)chips.push(`Arrival ${ex.arrival_time}`);if(ex.guest_count)chips.push(`${ex.guest_count} guests`);(ex.special_requests||[]).forEach(x=>chips.push(x));
 return chips.map(x=>`<span>${esc(x)}</span>`).join('');
}
function v28MessageDetail(m){
 const a=m.analysis||{}, analyzed=Object.keys(a).length>0, provider=m.draft_provider||'local';
 return `<article class="v28-conversation-card">
  <header class="v28-conversation-head"><button type="button" class="gmail-thread-back" id="v28MobileInboxBack" aria-label="Back to inbox">‹</button><div><span class="source">${esc(m.source)} · ${v28ReceptionStatus(m.status)}</span><h2>${esc(m.sender_name||'Guest')}</h2><p>${esc(m.property_name||'')}${m.reservation_arrival?` · ${fmtDate(m.reservation_arrival)} → ${fmtDate(m.reservation_departure)}`:''}</p></div><div class="v28-head-actions">${m.reservation_id?`<button id="openLinkedReservation">Open stay</button>`:''}<button id="archiveMessage">Archive</button></div></header>
  <section class="v28-thread">
   <div class="v28-thread-label">${v28('guestMessage')}</div><div class="v28-guest-bubble"><small>${esc(m.subject||'Message')}</small><p>${esc(m.body)}</p></div>
   ${analyzed?`<div class="v28-understood"><div><span class="eyebrow">ROSA UNDERSTOOD</span><div class="v28-chip-row">${v28AnalysisChips(a)}</div></div>${a.unresolved?.length?`<div class="v28-missing"><b>Needs confirmation</b>${a.unresolved.map(x=>`<p>${esc(x)}</p>`).join('')}</div>`:''}</div>`:''}
   <div class="v28-thread-label rosa">${v28('rosaDraft')}</div>
   ${analyzed?`<section class="v28-reply-composer"><div class="v28-reply-meta"><span class="v28-provider ${provider==='openai'?'luna':'local'}">${provider==='openai'?v28('luna'):v28('local')}</span><small>${v28('externalNote')}</small></div><textarea id="draftReply">${esc(m.draft_reply||a.draft_reply||'')}</textarea><div class="v28-reply-actions"><button class="btn" id="smartDraft">✦ ${v28('smartDraft')}</button><button class="btn" id="saveInboxDraft">${v28('save')}</button>${m.status==='analyzed'?`<button class="btn" id="applyInboxActions">${v28('apply')}</button>`:''}${['analyzed','actioned'].includes(m.status)?`<button class="btn primary" id="markReplySent">${v28('markSent')}</button>`:''}</div></section>`:`<section class="v28-analyze"><img class="delvane-primary-logo rosa-large-logo" src="/static/delvane-icon.png" alt="Delvane logo"><div><h3>Let Delvane understand this first.</h3><p>Structured facts and actions stay deterministic. Luna is used only when the wording actually benefits from it.</p></div><button class="btn primary" id="analyzeMessage">${v28('analyze')}</button></section>`}
  </section>
 </article>`;
}
function v28InboxView(items,selected,props,reservations){
 const list=items.length?items.map((m,i)=>`<button type="button" class="v28-inbox-row inbox-item ${selected?.id===m.id?'active':''}" data-message="${m.id}" data-search-text="${esc(`${m.sender_name||''} ${m.subject||''} ${m.body||''} ${m.source||''}`.toLowerCase())}"><span class="gmail-avatar gmail-avatar-${i%6}">${esc((m.sender_name||m.source||'?').trim().charAt(0).toUpperCase())}</span><span class="gmail-message-copy"><span class="gmail-row-top"><b>${esc(m.sender_name||'Guest')}</b><time>${esc(m.received_at||m.created_at||'')}</time></span><span class="gmail-subject">${esc(m.subject||m.property_name||'Guest message')}</span><span class="gmail-snippet">${esc((m.body||'').replace(/\s+/g,' ').slice(0,110))}${(m.body||'').length>110?'…':''}</span><span class="gmail-source-line"><span>${esc(m.source||m.property_name||'Message')}</span>${m.status==='new'?'<i class="gmail-unread-dot" aria-label="Unread"></i>':''}</span></span></button>`).join(''):`<div class="gmail-empty">Your inbox is clear.<small>Guest messages will appear here.</small></div>`;
 return `<section class="v28-inbox-workspace gmail-reception-workspace ${selected ? "v28-mobile-thread-open" : ""}"><aside class="v28-inbox-list gmail-reception-list"><div class="gmail-mobile-search"><button type="button" class="gmail-menu-icon" aria-label="Open navigation">☰</button><input id="v28GmailSearch" type="search" placeholder="Search in mail" aria-label="Search in mail"><span class="gmail-profile">R</span></div><div class="gmail-mobile-label">All inboxes</div><div class="v28-list-head gmail-desktop-list-head"><span>MESSAGES</span></div><div class="gmail-message-list">${list}</div></aside><main class="v28-inbox-main gmail-reception-main">${selected?v28MessageDetail(selected):`<div class="v28-empty hero gmail-desktop-empty">Select a message to review it.</div>`}</main></section>`;
}
function v28ScheduledCard(x){
 return `<article class="v28-scheduled-card status-${esc(x.status)}"><header><div><span>${esc(x.rule_label||x.subject||'Guest message')}</span><h3>${esc(x.guest_name||'Guest')} · ${esc(x.property_name||'')}</h3><p>${x.scheduled_for?new Date(x.scheduled_for).toLocaleString(rosaLocaleCode()):'Unscheduled'}</p></div><b>${v28ReceptionStatus(x.status)}</b></header><textarea data-outbox-body="${x.id}">${esc(x.body)}</textarea><footer><small>${esc(x.channel)} · no live external send</small><div><button data-outbox-save="${x.id}">${v28('save')}</button>${!['ready','simulated_sent','cancelled'].includes(x.status)?`<button data-outbox-approve="${x.id}">${v28('approve')}</button>`:''}${x.status!=='cancelled'?`<button data-outbox-send="${x.id}" class="primary">${v28('simulateSend')}</button><button data-outbox-cancel="${x.id}">${v28('cancel')}</button>`:''}</div></footer></article>`;
}
function v28ScheduledView(outbox){
 const active=outbox.filter(x=>x.status!=='cancelled');
 return `<section class="v28-scheduled"><div class="v28-safety-banner"><span>◎</span><div><b>Communication sandbox</b><p>${v28('externalNote')}</p></div></div><div class="v28-scheduled-list">${active.length?active.map(v28ScheduledCard).join(''):`<div class="v28-empty hero">${v28('noScheduled')}</div>`}</div></section>`;
}
function v28AutomationView(rules){
 return `<section class="v28-automation"><div class="v28-automation-hero"><div><span class="eyebrow">GUEST JOURNEY AUTOMATION</span><h2>Delvane prepares the next touchpoint before you think about it.</h2><p>Rules create drafts only. OBSERVE previews, ASSIST requests approval, and AUTONOMOUS can prepare approved items. No external channel is connected yet.</p></div><button class="btn primary" id="runAutomation">${v28('runNow')}</button></div><div class="v28-rule-grid">${rules.map(r=>`<article class="v28-rule-card"><header><div><span>${esc(r.trigger_key.replaceAll('_',' '))}</span><h3>${esc(r.label)}</h3></div><label class="v28-switch"><input type="checkbox" data-rule-enabled="${r.id}" ${r.enabled?'checked':''}><i></i></label></header><p>${esc(r.description)}</p><footer><label>${v28('authority')}<select data-rule-authority="${r.id}"><option value="ask" ${r.authority_mode==='ask'?'selected':''}>Ask owner</option><option value="auto" ${r.authority_mode==='auto'?'selected':''}>Automatic</option><option value="never" ${r.authority_mode==='never'?'selected':''}>Never</option></select></label><span>${r.run_count} evaluations</span></footer></article>`).join('')}</div></section>`;
}

ownerInbox=async function(selectedId=null){
 const active=window.__receptionTab||'inbox';
 const [summary,items,props,reservations,outbox,rules]=await Promise.all([api('/api/reception/summary'),api('/api/inbox'),api('/api/properties'),api('/api/reservations'),api('/api/communications/outbox'),api('/api/automation/rules')]);
 if(selectedId!==null&&selectedId!==undefined)activeInboxId=String(selectedId);const mobileReception=window.matchMedia('(max-width: 760px)').matches;if(!activeInboxId||!items.some(x=>String(x.id)===String(activeInboxId)))activeInboxId=mobileReception?null:(items[0]?String(items[0].id):null);const selected=items.find(x=>String(x.id)===String(activeInboxId))||null;
 const body=active==='scheduled'?v28ScheduledView(outbox):active==='automations'?v28AutomationView(rules):v28InboxView(items,selected,props,reservations);
 const content=`<section class="top compact v28-reception-top"><div><span class="eyebrow">ROSA RECEPTION · V2.8</span><h1>${v28('receptionTitle')}</h1><p>${v28('receptionDesc')}</p></div><button class="btn primary" id="v28NewMessage">+ ${v28('newMessage')}</button></section><section class="v28-reception-metrics"><article><span>New messages</span><strong>${summary.new}</strong></article><article><span>Awaiting approval</span><strong>${summary.waiting_approval}</strong></article><article><span>Prepared touchpoints</span><strong>${summary.scheduled}</strong></article><article><span>Live external sending</span><strong>OFF</strong></article></section>${v28ReceptionTabs(summary,active)}${body}${rosaBar()}`;
 app.innerHTML=shell(content,'inbox');wireShell();wireDelvane();
 document.querySelectorAll('[data-reception-tab]').forEach(b=>b.onclick=()=>{window.__receptionTab=b.dataset.receptionTab;ownerInbox()});
 // The message row itself is the interaction target. Normalize IDs to strings because HTML data attributes are strings.
 document.querySelectorAll('.gmail-reception-workspace [data-message]').forEach(row=>row.addEventListener('click',()=>ownerInbox(String(row.dataset.message))));
 $('#v28GmailSearch')?.addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();document.querySelectorAll('.gmail-message-list [data-message]').forEach(row=>{row.hidden=!row.dataset.searchText.includes(q)})});
 $('#v28MobileInboxBack')?.addEventListener('click',()=>{activeInboxId=null;ownerInbox()});
 document.querySelector('.gmail-menu-icon')?.addEventListener('click',()=>$('#mobileMenuBtn')?.click());

 function v28InboxView(items,selected,props,reservations){
 const list=items.length?items.map((m,i)=>`<button type="button" class="v28-inbox-row inbox-item ${selected?.id===m.id?'active':''}" data-message="${m.id}" data-search-text="${esc(`${m.sender_name||''} ${m.subject||''} ${m.body||''} ${m.source||''}`.toLowerCase())}"><span class="gmail-avatar gmail-avatar-${i%6}">${esc((m.sender_name||m.source||'?').trim().charAt(0).toUpperCase())}</span><span class="gmail-message-copy"><span class="gmail-row-top"><b>${esc(m.sender_name||'Guest')}</b><time>${esc(m.received_at||m.created_at||'')}</time></span><span class="gmail-subject">${esc(m.subject||m.property_name||'Guest message')}</span><span class="gmail-snippet">${esc((m.body||'').replace(/\s+/g,' ').slice(0,110))}${(m.body||'').length>110?'…':''}</span><span class="gmail-source-line"><span>${esc(m.source||m.property_name||'Message')}</span>${m.status==='new'?'<i class="gmail-unread-dot" aria-label="Unread"></i>':''}</span></span></button>`).join(''):`<div class="gmail-empty">Your inbox is clear.<small>Guest messages will appear here.</small></div>`;
 return `<section class="v28-inbox-workspace gmail-reception-workspace ${selected ? "v28-mobile-thread-open" : ""}"><aside class="v28-inbox-list gmail-reception-list"><div class="gmail-mobile-search"><button type="button" class="gmail-menu-icon" aria-label="Open navigation">☰</button><input id="v28GmailSearch" type="search" placeholder="Search in mail" aria-label="Search in mail"><span class="gmail-profile">R</span></div><div class="gmail-mobile-label">All inboxes</div><div class="v28-list-head gmail-desktop-list-head"><span>MESSAGES</span></div><div class="gmail-message-list">${list}</div></aside><main class="v28-inbox-main gmail-reception-main">${selected?v28MessageDetail(selected):`<div class="v28-empty hero gmail-desktop-empty">Select a message to review it.</div>`}</main></section>`;
}
 if(selected&&active==='inbox'){
   $('#analyzeMessage')?.addEventListener('click',async()=>{await api(`/api/inbox/${selected.id}/analyze`,{method:'POST'});ownerInbox(selected.id)});
   $('#smartDraft')?.addEventListener('click',async()=>{const b=$('#smartDraft');b.disabled=true;b.textContent='…';await api(`/api/inbox/${selected.id}/draft`,{method:'POST',body:JSON.stringify({tone:'warm_concise'})});ownerInbox(selected.id)});
   $('#saveInboxDraft')?.addEventListener('click',async()=>{await api(`/api/inbox/${selected.id}/draft`,{method:'PATCH',body:JSON.stringify({draft_reply:$('#draftReply')?.value||''})});const b=$('#saveInboxDraft');if(b)b.textContent='✓';});
   $('#applyInboxActions')?.addEventListener('click',async()=>{await api(`/api/inbox/${selected.id}/apply`,{method:'POST',body:JSON.stringify({draft_reply:$('#draftReply')?.value||null})});ownerInbox(selected.id)});
   $('#markReplySent')?.addEventListener('click',async()=>{await api(`/api/inbox/${selected.id}/reply-sent`,{method:'POST',body:JSON.stringify({draft_reply:$('#draftReply')?.value||null})});ownerInbox(selected.id)});
   $('#archiveMessage')?.addEventListener('click',async()=>{await api(`/api/inbox/${selected.id}/archive`,{method:'POST'});activeInboxId=null;ownerInbox()});
   $('#openLinkedReservation')?.addEventListener('click',()=>openReservationById(selected.reservation_id));
 }
 document.querySelectorAll('[data-outbox-save]').forEach(b=>b.onclick=async()=>{const id=b.dataset.outboxSave;const el=document.querySelector(`[data-outbox-body="${id}"]`);await api(`/api/communications/outbox/${id}`,{method:'PATCH',body:JSON.stringify({body:el?.value||''})});b.textContent='✓'});
 document.querySelectorAll('[data-outbox-approve]').forEach(b=>b.onclick=async()=>{await api(`/api/communications/outbox/${b.dataset.outboxApprove}/approve`,{method:'POST'});ownerInbox()});
 document.querySelectorAll('[data-outbox-send]').forEach(b=>b.onclick=async()=>{await api(`/api/communications/outbox/${b.dataset.outboxSend}/simulate-send`,{method:'POST'});ownerInbox()});
 document.querySelectorAll('[data-outbox-cancel]').forEach(b=>b.onclick=async()=>{await api(`/api/communications/outbox/${b.dataset.outboxCancel}`,{method:'PATCH',body:JSON.stringify({status:'cancelled'})});ownerInbox()});
 document.querySelectorAll('[data-rule-enabled]').forEach(x=>x.onchange=async()=>{await api(`/api/automation/rules/${x.dataset.ruleEnabled}`,{method:'PATCH',body:JSON.stringify({enabled:x.checked})})});
 document.querySelectorAll('[data-rule-authority]').forEach(x=>x.onchange=async()=>{await api(`/api/automation/rules/${x.dataset.ruleAuthority}`,{method:'PATCH',body:JSON.stringify({authority_mode:x.value})})});
 $('#runAutomation')?.addEventListener('click',async()=>{const b=$('#runAutomation');b.disabled=true;b.textContent='…';const r=await api('/api/automation/run',{method:'POST'});window.__receptionTab='scheduled';await ownerInbox();});
 setTimeout(translateRenderedUI,0);
};



