function v281(k){return V281_I18N[uiLang]?.[k]||V281_I18N.en[k]||k}

// These systems remain fully available, but they no longer own navigation destinations.
settingsNavigationGroups=function(){
 return [
   [v223('account'),[['team',v223('teamAccess'),'♙']]],
   [v223('rosaAutomation'),[['train',v223('trainDelvane'),'R'],['simulation',v223('simulationMode'),'◎']]],
   [v223('propertyOperations'),[['maintenance',v223('maintenance'),'◇'],['supplies',v223('supplies'),'▦']]],
   [v223('connectionsSecurity'),[['integrations',v223('integrations'),'↔'],['security',v223('securityCenter'),'⌾']]]
 ];
};

function v281RegistrationState(r,baseDate){
 if(r.registration_status==='complete')return {state:'ready',label:v281('registrationReady')};
 const today=baseDate||localISODate(new Date());
 return {state:'attention',label:r.arrival_date<=today?v281('registrationOwner'):v281('registrationWaiting')};
}

ownerToday=async function(){
 const [cmd,d]=await Promise.all([api('/api/operations/today-command'),api('/api/owner/dashboard')]);
 const turnovers=cmd.cleaning.filter(x=>x.deadline_time).length;
 const issueCount=cmd.maintenance.length;
 const tomorrow=localISODate(new Date(new Date(cmd.date+'T12:00:00').getTime()+86400000));
 const regStrip=cmd.registration_risks.length?`<section class="v281-registration-strip"><header><div><span class="eyebrow">${v281('registrationAction').toUpperCase()}</span><h2>${v281('registrationAttention')}</h2></div><strong>${cmd.registration_risks.length}</strong></header><div class="v281-registration-list">${cmd.registration_risks.map(r=>`<button data-open-res="${r.id}"><span class="v281-reg-mark">!</span><div><b>${esc(r.guest_name)}</b><small>${esc(r.property_name)} · ${r.arrival_date===cmd.date?v281('arrivesToday'):r.arrival_date===tomorrow?v281('arrivesTomorrow'):fmtDate(r.arrival_date)} · ${esc(r.arrival_time||r.checkin_time||'15:00')}</small></div><i>Open stay →</i></button>`).join('')}</div></section>`:'';
 const content=`<section class="top compact v25-command-top"><div><span class="eyebrow">${esc(cmd.date)}</span><h1>${v25('todayCommand')}</h1><p>${cmd.urgent_count?`<b>${cmd.urgent_count}</b> ${v25('urgent').toLowerCase()}`:v25('readyToFinish')}</p></div>${cmd.urgent_count?`<span class="v25-urgent-pill">${cmd.urgent_count} ${v25('urgent')}</span>`:'<span class="v25-clear-pill">✓</span>'}</section>
 <section class="v25-metric-row"><article><span>${localizeOperationalText('Arrivals')}</span><strong>${cmd.arrivals.length}</strong></article><article><span>${localizeOperationalText('Departures')}</span><strong>${cmd.departures.length}</strong></article><article><span>${v25('turnovers')}</span><strong>${turnovers}</strong></article><article><span>${v25('registrationIssues')}</span><strong>${cmd.registration_risks.length}</strong></article></section>
 ${regStrip}
 <section class="v25-today-board"><div class="v25-today-column"><header><span class="eyebrow">${localizeOperationalText('Arrivals')}</span><b>${cmd.arrivals.length}</b></header>${cmd.arrivals.length?cmd.arrivals.map(r=>`<button class="v25-action-row" data-open-res="${r.id}"><span class="v25-time">${esc(r.arrival_time||r.checkin_time||'15:00')}</span><span><b>${esc(r.guest_name)}</b><small>${esc(r.property_name)} · ${r.guest_count} ${localizeOperationalText('guests')}</small></span><i>${r.registration_status==='complete'?'✓':'!'}</i></button>`).join(''):`<div class="empty">—</div>`}</div>
 <div class="v25-today-column"><header><span class="eyebrow">${v25('turnovers')}</span><b>${cmd.cleaning.length}</b></header>${cmd.cleaning.length?cmd.cleaning.map(t=>`<button class="v25-action-row" data-property="${esc(d.properties.find(p=>p.name===t.property_name)?.id||'')}"><span class="v25-time">${esc(t.deadline_time||'—')}</span><span><b>${esc(t.property_name)}</b><small>${esc(t.assigned_name||localizeOperationalText('Unassigned'))} · ${statusLabel(t.status)}</small></span><i>↻</i></button>`).join(''):`<div class="empty">—</div>`}</div>
 <div class="v25-today-column"><header><span class="eyebrow">${v25('openMaintenance')}</span><b>${issueCount}</b></header>${cmd.maintenance.length?cmd.maintenance.slice(0,5).map(m=>`<button class="v25-action-row" data-maintenance-open="1"><span class="severity ${esc(m.severity)}">${esc(m.severity)}</span><span><b>${esc(m.title)}</b><small>${esc(m.property_name)} · ${compactStatus(m.status)}</small></span><i>›</i></button>`).join(''):`<div class="empty">—</div>`}</div></section>
 <section><div class="section-head"><div><span class="eyebrow">${localizeOperationalText('Properties')}</span><h2>${localizeOperationalText('Properties')}</h2></div></div><div class="property-grid">${d.properties.map(p=>`<button type="button" class="property property-click" data-property="${p.id}"><div class="property-top"><h3>${esc(p.name)}</h3><span class="state ${p.state}">${localizeOperationalText(p.state==='ready'?'Ready':p.state==='cleaning'?'Cleaning':'Attention')}</span></div><p>${p.reasons.length?esc(localizeOperationalText(p.reasons.join(' · '))):localizeOperationalText('No blockers detected.')}</p><div class="property-meta"><span>${localizeOperationalText('Next:')} ${p.next_arrival?fmtDate(p.next_arrival):'—'}</span><span class="property-open">${localizeOperationalText('Open →')}</span></div></button>`).join('')}</div></section>`;
 app.innerHTML=shell(content,'today');wireShell();
 document.querySelectorAll('[data-open-res]').forEach(b=>b.onclick=()=>openReservationById(b.dataset.openRes));
 document.querySelectorAll('[data-property]').forEach(b=>b.onclick=()=>b.dataset.property&&propertyOverviewModal(b.dataset.property));
 document.querySelectorAll('[data-maintenance-open]').forEach(b=>b.onclick=()=>ownerMaintenance());
 setTimeout(translateRenderedUI,0);
};

reservationModal=async function(r,props){
 if(!r)return legacyReservationModal(r,props);
 const d=await api(`/api/reservations/${r.id}/detail`),x=d.reservation,requests=requestList(x),reg=d.registration||[],cleaning=d.cleaning||[],gp=d.guest_profile;
 const completeCount=reg.length?reg.filter(g=>g.completeness==='complete').length:(x.registration_status==='complete'?x.guest_count:0);
 const expected=Math.max(x.guest_count,reg.length||0),regState=v281RegistrationState(x);
 const returnLabel=gp?(gp.stay_count>1?`${v281('returningGuest')} · ${gp.stay_count} ${v22('stays')}`:v281('newGuest')):'';
 document.body.insertAdjacentHTML('beforeend',`<div class="modal v25-modal" id="reservationModal"><div class="modal-card v25-reservation-workspace v281-reservation-workspace"><header class="v25-res-header"><div><span class="source">${esc(x.source)}${x.external_ref?' · '+esc(x.external_ref):''}</span><h2>${esc(x.guest_name)}</h2><p>${esc(x.property_name)} · ${fmtDate(x.arrival_date)} → ${fmtDate(x.departure_date)}</p>${gp?`<span class="v281-returning-badge ${gp.stay_count>1?'returning':'new'}">${esc(returnLabel)}</span>`:''}</div><div class="v25-res-head-actions"><button class="btn" id="v25EditBooking">${v25('editBooking')}</button><button class="modal-x" id="closeReservation">×</button></div></header>
 <section class="v25-res-stats"><article><span>${v25('payment')}</span><b>${esc(localizeOperationalText(x.payment_status||'unknown'))}</b><small>${x.total_huf?new Intl.NumberFormat(rosaLocaleCode()).format(x.total_huf)+' Ft':'—'}</small></article><article><span>${localizeOperationalText('Registration')}</span><b>${esc(localizeOperationalText(x.registration_status||'incomplete'))}</b><small>${completeCount}/${expected}</small></article><article><span>${v25('arrivalTime')}</span><b>${esc(x.arrival_time||x.checkin_time)}</b><small>${esc(x.property_name)}</small></article><article><span>${localizeOperationalText('Guest')}</span><b>${x.guest_count}</b><small>${esc(gp?.preferred_language||d.guest?.preferred_language||'—')}</small></article></section>
 <nav class="v25-res-tabs"><button class="active" data-r-tab="overview">${v25('stayOverview')}</button><button data-r-tab="prep">${v25('preparation')}</button><button data-r-tab="comms">${v25('communication')}</button><button data-r-tab="activity">${v25('activity')}</button></nav><div class="v25-res-body" id="v25ResBody"></div></div></div>`);
 const guestPanel=()=>`<section class="v25-detail-panel v281-guest-context"><div class="v281-panel-head"><span class="eyebrow">${v281('guestContext').toUpperCase()}</span>${gp?`<span class="v281-memory-status">${esc(returnLabel)}</span>`:''}</div>${gp?`<div class="v281-guest-name"><span class="guest-avatar">${esc(gp.full_name.split(/\s+/).map(v=>v[0]).slice(0,2).join('').toUpperCase())}</span><div><b>${esc(gp.full_name)}</b><small>${esc(gp.preferred_language||'—')}</small></div></div><div class="v281-pref-list">${gp.preferences?.length?gp.preferences.slice(0,4).map(p=>`<span><b>${esc(p.preference_key.replaceAll('_',' '))}</b>${esc(p.preference_value)}</span>`).join(''):`<small>${v281('noPreferences')}</small>`}</div><button class="btn v281-view-guest" data-guest-history="${gp.id}">${v281('viewHistory')}</button>`:`<div class="empty">—</div>`}</section>`;
 const registrationPanel=()=>`<section class="v25-detail-panel v281-registration-panel ${regState.state}"><div class="v281-panel-head"><span class="eyebrow">${v281('registrationAction').toUpperCase()}</span><span class="state ${regState.state==='ready'?'ready':'attention'}">${esc(regState.label)}</span></div><div class="v281-reg-progress"><div><i style="width:${Math.round(completeCount/Math.max(1,expected)*100)}%"></i></div><b>${completeCount}/${expected}</b></div><div class="v281-reg-people">${reg.length?reg.map(g=>`<div><span class="reg-dot ${g.completeness==='complete'?'done':''}"></span><span><b>${esc(g.full_name)}</b><small>${esc(g.nationality||'—')} · ${esc(g.completeness)}</small></span></div>`).join(''):`<p>${x.registration_status==='complete'?v281('registrationReady'):v281('registrationWaiting')}</p>`}</div><div class="v281-reg-actions">${x.registration_status!=='complete'?`<button class="btn primary" id="v281GuestLink">Send guest check-in link</button><button class="btn" id="v281PrepareReminder">${v281('prepareReminder')}</button><button class="btn" id="v281OpenReception">${v281('openReception')}</button>`:''}<button class="btn" id="v281VerifyGuests">Review identity verification</button></div>${x.registration_status==='complete'?`<div class="v281-reg-ready">✓ ${v281('registrationReady')}</div>`:''}</section>`;
 const body=$('#v25ResBody');
 const panes={
  overview:()=>`<div class="v281-res-grid"><section class="v25-detail-panel"><span class="eyebrow">${v25('stayOverview')}</span><div class="v25-kv"><span>${localizeOperationalText('Property')}</span><b>${esc(x.property_name)}</b><small>${esc(x.address||'')}</small></div><div class="v25-kv"><span>${localizeOperationalText('Check-in')}</span><b>${esc(x.checkin_time)}</b></div><div class="v25-kv"><span>${localizeOperationalText('Checkout')}</span><b>${esc(x.checkout_time)}</b></div><div class="v25-kv"><span>${v223('specialRequests')}</span><b>${requests.length?requests.map(esc).join(' · '):'—'}</b></div></section>${guestPanel()}<section class="v25-detail-panel"><span class="eyebrow">${v25('preparation')}</span><label>${v25('arrivalTime')}<input id="v25ArrivalTime" type="time" value="${esc(x.arrival_time||'')}"></label><label>${v25('payment')}<select id="v25Payment">${['unknown','unpaid','partial','paid','refunded'].map(v=>`<option value="${v}" ${x.payment_status===v?'selected':''}>${localizeOperationalText(v)}</option>`).join('')}</select></label><label>${localizeOperationalText('Registration')}<select id="v25Registration">${['incomplete','pending','complete'].map(v=>`<option value="${v}" ${x.registration_status===v?'selected':''}>${localizeOperationalText(v)}</option>`).join('')}</select></label><button class="btn primary" id="v25SaveOps">${localizeOperationalText('Save')}</button></section></div><section class="v25-detail-panel" id="v281ChannexDeliveryPanel"><span class="eyebrow">CHANNEL DISTRIBUTION</span><div class="v25-kv"><span>Availability update</span><b>Checking Channex delivery…</b><small>This reservation's availability task will appear here when Delvane has the Channex task ID.</small></div></section>`,
  prep:()=>`<div class="v25-res-two">${registrationPanel()}<section class="v25-detail-panel"><span class="eyebrow">${v25('checklist')}</span>${cleaning.length?cleaning.map(t=>`<div class="v25-clean-link"><div><b>${esc(t.title)}</b><small>${fmtDate(t.scheduled_date)} · ${esc(t.assigned_name||localizeOperationalText('Unassigned'))}</small></div><span class="state ${t.status==='complete'?'ready':t.status==='in_progress'?'cleaning':'attention'}">${statusLabel(t.status)}</span></div>`).join(''):`<div class="empty">—</div>`}${d.maintenance?.length?`<div class="v25-maint-warning"><b>${v25('openMaintenance')}</b><span>${d.maintenance.map(m=>esc(m.title)).join(' · ')}</span></div>`:''}</section></div>`,
  comms:()=>`<div class="v25-res-two"><section class="v25-detail-panel"><span class="eyebrow">${localizeOperationalText('Messages')}</span>${d.messages.length?d.messages.map(m=>`<article class="v25-message-item"><small>${esc(m.source)} · ${new Date(m.received_at).toLocaleString(rosaLocaleCode())}</small><b>${esc(m.sender_name||m.subject||'')}</b><p>${esc(m.body)}</p></article>`).join(''):`<div class="empty">${v25('noMessages')}</div>`}</section><section class="v25-detail-panel"><span class="eyebrow">${v25('addNote')}</span><textarea id="v25Note" placeholder="${v25('notePlaceholder')}"></textarea><button class="btn primary" id="v25AddNote">${v25('addNote')}</button><div class="v25-note-list">${d.notes.length?d.notes.map(n=>`<article><b>${esc(n.author_name||'Delvane')}</b><small>${new Date(n.created_at).toLocaleString(rosaLocaleCode())}</small><p>${esc(n.body)}</p></article>`).join(''):`<div class="empty">${v25('noNotes')}</div>`}</div></section></div>`,
  activity:()=>`<section class="v25-detail-panel"><span class="eyebrow">${v25('activity')}</span><div class="life-timeline">${d.events.length?d.events.map(e=>`<article><i></i><div><time>${new Date(e.created_at).toLocaleString(rosaLocaleCode())}</time><b>${esc(localizeOperationalText(e.summary))}</b><span>${esc(e.event_type)}</span></div></article>`).join(''):`<div class="empty">${v25('noActivity')}</div>`}</div></section>`
 };
 const wirePane=name=>{
   body.innerHTML=panes[name]();
   if(name==='overview'){
     $('#v25SaveOps').onclick=async()=>{await api(`/api/reservations/${r.id}/operations`,{method:'PATCH',body:JSON.stringify({arrival_time:$('#v25ArrivalTime').value||'',payment_status:$('#v25Payment').value,registration_status:$('#v25Registration').value})});$('#reservationModal').remove();openReservationById(r.id)};
     const renderChannexDelivery=(status)=>{
       const panel=$('#v281ChannexDeliveryPanel'); if(!panel)return;
       const items=status?.delivered||[]; const pending=status?.pending||[]; const ids=items.flatMap(x=>x.task_ids||[]);
       if(ids.length){
         panel.innerHTML=`<span class="eyebrow">CHANNEL DISTRIBUTION</span><div class="v25-kv"><span>Availability update</span><b>Delivered to Channex</b><small>Task ID${ids.length>1?'s':''}: ${esc(ids.join(', '))}</small></div>`;
       }else if(pending.length){
         panel.innerHTML=`<span class="eyebrow">CHANNEL DISTRIBUTION</span><div class="v25-kv"><span>Availability update</span><b>Queued for Channex</b><small>Delvane has the update safely queued.</small><button class="btn" id="v281RetryChannexAvailability">Send to Channex now</button></div>`;
         $('#v281RetryChannexAvailability').onclick=async()=>{const b=$('#v281RetryChannexAvailability');b.disabled=true;b.textContent='Sending…';try{const out=await api(`/api/reservations/${r.id}/channex-availability-delivery/retry`,{method:'POST'});renderChannexDelivery(out.status||{});if((out.failed||[]).length&&!((out.status?.delivered||[]).length)){const err=out.failed.map(x=>x.error).join(' · ');panel.querySelector('small').textContent=`Channex delivery failed: ${err}`;}}catch(err){panel.querySelector('small').textContent=`Channex delivery failed: ${err.message}`;b.disabled=false;b.textContent='Send to Channex now';}};
       }else{
         panel.innerHTML=`<span class="eyebrow">CHANNEL DISTRIBUTION</span><div class="v25-kv"><span>Availability update</span><b>No delivery recorded for this reservation</b><small>No matching delivery was found. Publish the reservation current availability to Channex now.</small><button class="btn" id="v281RetryChannexAvailability">Send current availability to Channex</button></div>`;
         $('#v281RetryChannexAvailability').onclick=async()=>{const b=$('#v281RetryChannexAvailability');b.disabled=true;b.textContent='Sending…';try{const out=await api(`/api/reservations/${r.id}/channex-availability-delivery/retry`,{method:'POST'});renderChannexDelivery(out.status||{});if((out.failed||[]).length&&!((out.status?.delivered||[]).length)){panel.querySelector('small').textContent=`Channex delivery failed: ${out.failed.map(x=>x.error).join(' · ')}`;b.disabled=false;b.textContent='Send current availability to Channex';}}catch(err){panel.querySelector('small').textContent=`Channex delivery failed: ${err.message}`;b.disabled=false;b.textContent='Send current availability to Channex';}};
       }
     };
     (async()=>{let attempts=0; const poll=async()=>{attempts++;try{const status=await api(`/api/reservations/${r.id}/channex-availability-delivery`);renderChannexDelivery(status);if((status.delivered||[]).length||!(status.pending||[]).length||attempts>=10)return;}catch(_){} if(attempts<10)setTimeout(poll,1500)};poll()})();
   }
   if(name==='prep'){
     $('#v281VerifyGuests')?.addEventListener('click',async()=>{
       const b=$('#v281VerifyGuests');b.disabled=true;b.textContent='Loading…';
       try{
         const status=await api(`/api/reservations/${r.id}/guest-checkin-status`);const guests=status.guests||[];
         const renderGuests=()=>guests.map(g=>{const state=g.verification_status||'not_submitted';const label=state==='verified'?'Verified':state==='needs_review'?'Needs review':state==='rejected'?'Rejected':'Not submitted';return `<article class="v25-kv" style="margin:12px 0"><span>${esc(g.full_name||'Guest')}</span><b>${label}</b><small>Registration data: ${esc(g.completeness)}${g.verified_at?` · Verified ${new Date(g.verified_at).toLocaleString(rosaLocaleCode())}`:''}${g.review_note?` · ${esc(g.review_note)}`:''}</small>${g.completeness==='complete'&&state!=='verified'?`<label style="display:block;margin-top:10px">Verification method<select data-method="${esc(g.id)}"><option value="in_person">Checked in person</option><option value="video_call">Verified by video call</option><option value="identity_image">Reviewed identity image</option><option value="manual_review">Manual review</option></select></label><label style="display:block;margin-top:8px">Review note<input data-note="${esc(g.id)}" maxlength="1000" placeholder="Optional note"></label><button class="btn primary" data-verify="${esc(g.id)}" style="margin-top:8px">Verify identity</button><button class="btn" data-reject="${esc(g.id)}" style="margin-top:8px">Needs correction</button>`:''}</article>`}).join('');
         document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="guestVerifyModal"><div class="modal-card"><div class="modal-title"><div><span class="eyebrow">GUEST PRE-CHECK-IN</span><h2>Identity verification</h2></div><button class="modal-x" id="closeGuestVerify">×</button></div><p class="muted">Guest-submitted details are not verified automatically. Check the guest's identity and data before approving registration for VIZA. Delvane does not store document images.</p><div id="guestVerifyList">${renderGuests()}</div><div class="modal-actions"><button class="btn primary" id="doneGuestVerify">Done</button></div></div></div>`);
         const closeVerify=()=>$('#guestVerifyModal')?.remove();$('#closeGuestVerify').onclick=closeVerify;$('#doneGuestVerify').onclick=()=>{closeVerify();$('#reservationModal')?.remove();openReservationById(r.id)};
         const wireVerificationButtons=()=>{document.querySelectorAll('[data-verify]').forEach(el=>el.onclick=()=>submitDecision(el.dataset.verify,'verify'));document.querySelectorAll('[data-reject]').forEach(el=>el.onclick=()=>submitDecision(el.dataset.reject,'reject'))};
         const submitDecision=async(id,decision)=>{const selector=decision==='verify'?'verify':'reject';const btn=document.querySelector(`[data-${selector}="${CSS.escape(id)}"]`);if(btn){btn.disabled=true;btn.textContent='Saving…'}try{const method=document.querySelector(`[data-method="${CSS.escape(id)}"]`)?.value||'manual_review';const note=document.querySelector(`[data-note="${CSS.escape(id)}"]`)?.value||'';await api(`/api/reservations/${r.id}/guests/${encodeURIComponent(id)}/verify`,{method:'POST',body:JSON.stringify({decision,verification_method:method,review_note:note})});const fresh=await api(`/api/reservations/${r.id}/guest-checkin-status`);guests.splice(0,guests.length,...(fresh.guests||[]));$('#guestVerifyList').innerHTML=renderGuests();wireVerificationButtons()}catch(err){alert(err.message);if(btn){btn.disabled=false;btn.textContent=decision==='verify'?'Verify identity':'Needs correction'}}};wireVerificationButtons();
       }catch(err){alert(err.message)}finally{b.disabled=false;b.textContent='Review identity verification'}
     });
     $('#v281GuestLink')?.addEventListener('click',async()=>{const b=$('#v281GuestLink');b.disabled=true;b.textContent='Generating…';try{const out=await api(`/api/reservations/${r.id}/guest-checkin-links`);const links=out.links||[];document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="guestLinkModal"><div class="modal-card"><div class="modal-title"><div><span class="eyebrow">GUEST PRE-CHECK-IN</span><h2>Secure guest links</h2></div><button class="modal-x" id="closeGuestLinks">×</button></div><p class="muted">Send each guest their own link. The document image stays on the guest's phone; Delvane receives only the extracted registration data.</p>${links.map(x=>`<div class="v25-kv" style="margin:12px 0"><span>${esc(x.guest_name)}</span><b>${esc(x.completeness)}</b><small style="word-break:break-all">${esc(x.url)}</small><div style="margin-top:8px"><button class="btn" data-copy-link="${esc(x.url)}">Copy link</button></div></div>`).join('')}<div class="modal-actions"><button class="btn primary" id="doneGuestLinks">Done</button></div></div></div>`);$('#closeGuestLinks').onclick=()=>$('#guestLinkModal')?.remove();$('#doneGuestLinks').onclick=()=>$('#guestLinkModal')?.remove();document.querySelectorAll('[data-copy-link]').forEach(el=>el.onclick=async()=>{await navigator.clipboard.writeText(el.dataset.copyLink);el.textContent='Copied';setTimeout(()=>el.textContent='Copy link',1200)});}catch(err){alert(err.message)}finally{b.disabled=false;b.textContent='Send guest check-in link';}});
     $('#v281PrepareReminder')?.addEventListener('click',async()=>{const b=$('#v281PrepareReminder');b.disabled=true;b.textContent='…';const out=await api(`/api/reservations/${r.id}/registration-reminder`,{method:'POST'});b.textContent=v281('preparedReception');b.classList.remove('primary');b.classList.add('success');});
     $('#v281OpenReception')?.addEventListener('click',()=>{close();window.__receptionTab='scheduled';ownerInbox()});
   }
   if(name==='comms')$('#v25AddNote').onclick=async()=>{const text=$('#v25Note').value.trim();if(!text)return;await api(`/api/reservations/${r.id}/notes`,{method:'POST',body:JSON.stringify({body:text})});$('#reservationModal').remove();openReservationById(r.id)};
   document.querySelectorAll('[data-guest-history]').forEach(b=>b.onclick=()=>guestProfileModal(b.dataset.guestHistory));
 };
 const close=()=>$('#reservationModal')?.remove();
 wirePane('overview');document.querySelectorAll('[data-r-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-r-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');wirePane(b.dataset.rTab)});
 $('#closeReservation').onclick=close;$('#reservationModal').onclick=e=>{if(e.target.id==='reservationModal')close()};$('#v25EditBooking').onclick=()=>{close();legacyReservationModal(r,props)};
};

const v281MessageDetailBase=v28MessageDetail;
v28MessageDetail=function(m){
 const base=v281MessageDetailBase(m),g=m.guest_context;
 if(!g)return base;
 const memory=`<section class="v281-reception-guest"><div><span class="eyebrow">${v281('guestContext').toUpperCase()}</span><b>${g.stays>1?`${v281('returningGuest')} · ${g.stays} ${v22('stays')}`:v281('newGuest')}</b></div><div class="v281-reception-prefs">${g.preferences?.length?g.preferences.slice(0,3).map(p=>`<span>${esc(p.preference_value)}</span>`).join(''):`<small>${v281('noPreferences')}</small>`}</div><button data-v281-guest="${g.id}">${v281('viewHistory')}</button></section>`;
 return base.replace('<section class="v28-thread">',memory+'<section class="v28-thread">');
};
const v281OwnerInboxBase=ownerInbox;
ownerInbox=async function(selectedId=null){await v281OwnerInboxBase(selectedId);document.querySelectorAll('[data-v281-guest]').forEach(b=>b.onclick=()=>guestProfileModal(b.dataset.v281Guest));};

// Old direct routes resolve into contextual surfaces rather than resurrecting list pages.
const v281NavigateBase=navigate;
navigate=async function(v){
 if(v==='guests'){openGlobalSearch();return;}
 if(v==='registration'){return ownerToday();}
 return v281NavigateBase(v);
};


