// ROSA V2.8.2 — Team & Access workspace
const V282_ROLE_COPY={
 owner:{title:'Owner',desc:'Full workspace control, including organization settings and team accounts.'},
 manager:{title:'Manager',desc:'Runs reservations, guests and operations, but cannot create or change team accounts.'},
 cleaner:{title:'Cleaner',desc:'Sees assigned cleaning work and can report maintenance issues. No guest documents or financial data.'},
 maintenance:{title:'Maintenance',desc:'Sees maintenance work needed to resolve property issues. No reservation or guest-data access.'}
};
function v282When(v){
 if(!v)return 'Never';
 const d=new Date(v),diff=Date.now()-d.getTime();
 if(!Number.isFinite(diff))return v;
 const mins=Math.floor(diff/60000);if(mins<1)return 'Just now';if(mins<60)return `${mins}m ago`;
 const hrs=Math.floor(mins/60);if(hrs<24)return `${hrs}h ago`;
 const days=Math.floor(hrs/24);if(days<14)return `${days}d ago`;
 return d.toLocaleDateString(rosaLocaleCode());
}
function v282Initials(name=''){return name.split(/\s+/).filter(Boolean).map(x=>x[0]).slice(0,2).join('').toUpperCase()||'R'}
function v282RolePill(role){return `<span class="v282-role role-${esc(role)}">${esc(V282_ROLE_COPY[role]?.title||roleLabel(role))}</span>`}
function v282Security(m){
 return `<div class="v282-security-chips"><span class="${m.email_verified?'good':'warn'}">${m.email_verified?'✓ Email verified':'! Email unverified'}</span><span class="${m.mfa_enabled?'good':''}">${m.mfa_enabled?'✓ MFA':'MFA off'}</span>${m.active_sessions?`<span>${m.active_sessions} active session${m.active_sessions===1?'':'s'}</span>`:''}</div>`;
}
function v282MemberCard(m,canManage){
 const work=m.upcoming_cleaning+m.open_maintenance;
 return `<article class="v282-person-card ${m.active?'':'inactive'}" data-team-member="${m.id}">
   <div class="v282-person-head"><div class="v282-avatar">${esc(v282Initials(m.full_name))}</div><div class="v282-person-name"><div>${v282RolePill(m.role)}${m.active?'':'<span class="v282-suspended">Suspended</span>'}</div><h3>${esc(m.full_name)}</h3><p>${esc(m.job_title||V282_ROLE_COPY[m.role]?.title||roleLabel(m.role))}</p></div>${canManage?`<button class="btn v282-edit" data-edit-member="${m.id}">Manage</button>`:''}</div>
   <div class="v282-contact"><span><small>Email</small><b>${esc(m.email)}</b></span><span><small>Phone</small><b>${esc(m.phone||'Not added')}</b></span></div>
   ${v282Security(m)}
   <div class="v282-person-stats"><span><b>${work}</b><small>open / next 7 days</small></span><span><b>${m.in_progress}</b><small>in progress</small></span><span><b>${m.completed_30d}</b><small>completed 30d</small></span><span><b>${v282When(m.last_login_at)}</b><small>last sign-in</small></span></div>
 </article>`;
}
function v282AccessView(d){
 const roles=['owner','manager','cleaner','maintenance'];
 const groupNames=['Business & people','Reservations & guests','Guest communication','Operations','Maintenance','Supplies','Delvane knowledge','Security & integrations'];
 return `<section class="v282-access-intro"><div><span class="eyebrow">ACCESS MODEL</span><h2>People see only what their job requires.</h2><p>Access is enforced by Delvane's backend role permissions, not just hidden buttons in the interface.</p></div><button class="btn" data-nav-security>Open Security Center</button></section>
 <section class="v282-role-grid">${roles.map(role=>{const r=d.roles[role];return `<article class="v282-role-card"><header>${v282RolePill(role)}<h3>${V282_ROLE_COPY[role].title}</h3><p>${V282_ROLE_COPY[role].desc}</p></header><div class="v282-role-groups">${groupNames.map(name=>{const g=r.groups.find(x=>x.label===name);return `<div class="${g?.enabled?'allowed':'blocked'}"><i>${g?.enabled?'✓':'—'}</i><span>${esc(name)}</span></div>`}).join('')}</div></article>`}).join('')}</section>
 <section class="v282-access-health"><div class="section-head"><div><span class="eyebrow">ACCESS HEALTH</span><h2>Account posture</h2></div></div><div class="v282-health-grid"><article><strong>${d.stats.unverified}</strong><span>unverified email${d.stats.unverified===1?'':'s'}</span><small>Email verification is separate from account activation.</small></article><article><strong>${d.stats.active_sessions}</strong><span>active session${d.stats.active_sessions===1?'':'s'}</span><small>Owners can revoke a team member's sessions instantly.</small></article><article><strong>${d.members.filter(x=>x.mfa_enabled).length}</strong><span>MFA enabled</span><small>MFA state is visible here; enrollment remains part of Security.</small></article></div></section>`;
}
function v282WorkloadView(d){
 const workers=d.members.filter(m=>['cleaner','maintenance'].includes(m.role));
 const max=Math.max(1,...workers.map(m=>m.upcoming_cleaning+m.open_maintenance));
 return `<section class="v282-workload-summary"><div class="section-head"><div><span class="eyebrow">NEXT 7 DAYS</span><h2>Workload by person</h2></div></div><div class="v282-load-list">${workers.length?workers.map(m=>{const n=m.upcoming_cleaning+m.open_maintenance;return `<article><div class="v282-load-person"><span class="v282-avatar small">${esc(v282Initials(m.full_name))}</span><span><b>${esc(m.full_name)}</b><small>${esc(V282_ROLE_COPY[m.role].title)} · ${n} open</small></span></div><div class="v282-load-bar"><i style="width:${Math.max(4,Math.round(n/max*100))}%"></i></div><span>${m.upcoming_cleaning} clean · ${m.open_maintenance} maintenance</span></article>`}).join(''):'<div class="empty">No operational workers yet.</div>'}</div></section>
 <section><div class="section-head"><div><span class="eyebrow">ASSIGNMENTS</span><h2>Upcoming work</h2></div></div><div class="v282-work-table">${d.workload.length?d.workload.map(w=>`<article><span class="v282-work-kind ${esc(w.kind)}">${esc(w.kind)}</span><div><b>${esc(w.title)}</b><small>${esc(w.property_name)} · ${fmtDate(w.scheduled_date)}</small></div><span>${esc(w.assigned_name||'Unassigned')}</span><span class="state ${w.status==='in_progress'?'cleaning':w.status==='complete'?'ready':'attention'}">${esc(compactStatus(w.status))}</span></article>`).join(''):'<div class="empty">No upcoming operational work.</div>'}</div></section>`;
}

ownerTeam=async function(){
 const d=await api('/api/team/overview');
 const tab=window.__teamAccessTab||'people';
 const people=`<section class="v282-people-grid">${d.members.map(m=>v282MemberCard(m,d.can_manage)).join('')}</section>`;
 const pane=tab==='access'?v282AccessView(d):tab==='workload'?v282WorkloadView(d):people;
 const content=`<section class="top compact v282-team-hero"><div><span class="eyebrow">TEAM & ACCESS</span><h1>Your people, their work, and exactly what they can see.</h1><p>Add cleaners, maintenance workers and managers, review access, suspend accounts and understand workload without mixing it into the day-to-day task screens.</p></div>${d.can_manage?'<button class="btn primary" id="v282AddMember">+ Add team member</button>':'<span class="v282-readonly">Manager view · owner controls accounts</span>'}</section>
 <section class="v282-team-metrics"><article><strong>${d.stats.active}</strong><span>active people</span></article><article><strong>${d.stats.cleaners}</strong><span>cleaners</span></article><article><strong>${d.stats.maintenance}</strong><span>maintenance</span></article><article class="${d.stats.unverified?'attention':''}"><strong>${d.stats.unverified}</strong><span>access attention</span></article></section>
 <nav class="v282-team-tabs"><button data-team-tab="people" class="${tab==='people'?'active':''}">People <span>${d.members.length}</span></button><button data-team-tab="access" class="${tab==='access'?'active':''}">Access & roles</button><button data-team-tab="workload" class="${tab==='workload'?'active':''}">Workload</button></nav>
 <div class="v282-team-pane">${pane}</div>${rosaBar()}`;
 app.innerHTML=shell(content,'team');wireShell();wireDelvane();
 document.querySelectorAll('[data-team-tab]').forEach(b=>b.onclick=()=>{window.__teamAccessTab=b.dataset.teamTab;ownerTeam()});
 $('#v282AddMember')?.addEventListener('click',()=>v282TeamMemberModal(null,d));
 document.querySelectorAll('[data-edit-member]').forEach(b=>b.onclick=()=>v282TeamMemberModal(d.members.find(x=>x.id===b.dataset.editMember),d));
 document.querySelector('[data-nav-security]')?.addEventListener('click',()=>ownerSecurity());
 setTimeout(translateRenderedUI,0);
};

function v282TeamMemberModal(member,d){
 const editing=!!member,canManage=d.can_manage;
 if(!canManage)return;
 const role=member?.role||'cleaner';
 document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="v282MemberModal"><form class="modal-card v282-member-modal" id="v282MemberForm">
  <div class="modal-title"><div><span class="eyebrow">${editing?'TEAM ACCOUNT':'NEW TEAM MEMBER'}</span><h2>${editing?esc(member.full_name):'Add someone to Delvane'}</h2><p>${editing?'Update their identity, role and access state.':'Create an account for a cleaner, maintenance worker, manager or another owner.'}</p></div><button type="button" class="modal-x" id="v282CloseMember">×</button></div>
  <div class="v282-form-grid"><label>Full name<input id="v282Name" value="${esc(member?.full_name||'')}" required></label><label>Email<input id="v282Email" type="email" value="${esc(member?.email||'')}" required></label><label>Phone <small>optional</small><input id="v282Phone" value="${esc(member?.phone||'')}"></label><label>Job title <small>optional</small><input id="v282Title" value="${esc(member?.job_title||'')}"></label><label>Delvane role<select id="v282Role">${['cleaner','maintenance','manager','owner'].map(r=>`<option value="${r}" ${(member?.role||'cleaner')===r?'selected':''}>${V282_ROLE_COPY[r].title}</option>`).join('')}</select></label>${editing?`<label>Account status<select id="v282Active"><option value="1" ${member.active?'selected':''}>Active</option><option value="0" ${!member.active?'selected':''}>Suspended</option></select></label>`:''}</div>
  <section class="v282-role-preview" id="v282RolePreview"></section>
  ${editing?`<section class="v282-account-tools"><div><span class="eyebrow">ACCESS TOOLS</span><p>Resetting access creates a new password and signs this person out everywhere. Revoking sessions keeps the current password.</p></div><div><button type="button" class="btn" id="v282ResetAccess">Reset access</button><button type="button" class="btn" id="v282RevokeSessions">Revoke sessions</button></div></section>`:''}
  <p class="form-error" id="v282MemberError"></p><div class="modal-actions"><button type="button" class="btn" id="v282CancelMember">Cancel</button><button class="btn primary" type="submit">${editing?'Save changes':'Create account'}</button></div>
 </form></div>`);
 const modal=$('#v282MemberModal'),close=()=>modal?.remove();$('#v282CloseMember').onclick=close;$('#v282CancelMember').onclick=close;modal.onclick=e=>{if(e.target===modal)close()};
 const preview=()=>{const r=$('#v282Role').value,c=V282_ROLE_COPY[r],groups=d.roles[r]?.groups||[];$('#v282RolePreview').innerHTML=`<div>${v282RolePill(r)}<b>${esc(c.desc)}</b></div><div>${groups.filter(g=>g.enabled).map(g=>`<span>✓ ${esc(g.label)}</span>`).join('')}</div>${r==='owner'?'<small>Owner accounts can manage other team accounts. Use this role sparingly.</small>':''}`};
 $('#v282Role').onchange=preview;preview();
 $('#v282MemberForm').onsubmit=async e=>{e.preventDefault();const payload={full_name:$('#v282Name').value,email:$('#v282Email').value,phone:$('#v282Phone').value,job_title:$('#v282Title').value,role:$('#v282Role').value};if(editing)payload.active=$('#v282Active').value==='1';try{const out=await api(editing?`/api/team/members/${member.id}`:'/api/team/members',{method:editing?'PATCH':'POST',body:JSON.stringify(payload)});close();if(out.setup_password)v282SetupPasswordModal(payload.full_name,payload.email,out.setup_password);else ownerTeam()}catch(err){$('#v282MemberError').textContent=err.message}};
 $('#v282ResetAccess')?.addEventListener('click',async()=>{if(!confirm(`Generate a new password for ${member.full_name} and sign them out everywhere?`))return;try{const out=await api(`/api/team/members/${member.id}/reset-access`,{method:'POST'});close();v282SetupPasswordModal(member.full_name,member.email,out.setup_password,true)}catch(err){$('#v282MemberError').textContent=err.message}});
 $('#v282RevokeSessions')?.addEventListener('click',async()=>{if(!confirm(`Sign ${member.full_name} out of all Delvane sessions?`))return;try{await api(`/api/team/members/${member.id}/revoke-sessions`,{method:'POST'});$('#v282MemberError').textContent='✓ Sessions revoked.';setTimeout(()=>{close();ownerTeam()},500)}catch(err){$('#v282MemberError').textContent=err.message}});
}
function v282SetupPasswordModal(name,email,password,reset=false){
 const details=`Delvane\nName: ${name}\nEmail: ${email}\nSetup password: ${password}`;
 document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="v282PasswordModal"><div class="modal-card v282-password-modal"><span class="eyebrow">${reset?'ACCESS RESET':'ACCOUNT CREATED'}</span><h2>Give these details to ${esc(name)}.</h2><p>Delvane stores only the password hash. <b>This password is shown once.</b> Do not send it through a public channel.</p><div class="v282-credential"><span>Email</span><b>${esc(email)}</b><span>Setup password</span><code id="v282PasswordValue">${esc(password)}</code></div><div class="modal-actions"><button class="btn" id="v282CopyDetails">Copy setup details</button><button class="btn primary" id="v282DonePassword">Done</button></div><small id="v282CopyState"></small></div></div>`);
 const close=()=>{$('#v282PasswordModal')?.remove();ownerTeam()};$('#v282DonePassword').onclick=close;$('#v282PasswordModal').onclick=e=>{if(e.target.id==='v282PasswordModal')close()};$('#v282CopyDetails').onclick=async()=>{try{await navigator.clipboard.writeText(details);$('#v282CopyState').textContent='✓ Copied.'}catch{$('#v282CopyState').textContent='Copy unavailable — select the details manually.'}};
}
